INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C1','kor',1,1,'u2',1,'받침이 있는 글자 알아보기 — 글자 아래쪽에 자음자가 하나 더 있으면 받침이 있는 글자, 아래쪽이 비어 있으면 받침이 없는 글자임을 알고 가르기(「오」의 ㅇ은 위쪽 첫 자음자)',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C2','kor',1,1,'u2',3,'받침이 있는 글자의 짜임 — 첫 자음자 + 모음자 + 받침, 모음자가 옆에 서든(산) 아래에 쌓이든(손) 받침은 늘 맨 아래쪽에 들어감을 알고 글자를 세 부분으로 나누기',ARRAY['2국04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C3','kor',1,1,'u2',3,'받침을 더해 글자 만들기 — 받침 없는 글자 아래쪽에 자음자를 더해 새 글자를 만들고(차 → 창), 받침 소리까지 끝까지 읽기',ARRAY['2국04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C4','kor',1,1,'u2',5,'여러 가지 받침 읽기 — 받침 ㄱ·ㄴ·ㄷ·ㄹ·ㅁ·ㅂ·ㅇ이 들어간 글자를 또박또박 읽고, 받침마다 끝소리가 다름(짧게 닫힘·콧소리·입술 다물기·코에서 울림)을 알기',ARRAY['2국04-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C5','kor',1,1,'u2',5,'받침이 바뀌면 글자가 바뀌어요 — 같은 글자에 받침만 바꾸면(박·반·발·밤·밥·방) 소리도 뜻도 달라지고, 받침이 같아도 자음자·모음자가 다르면 다른 글자임을 알기',ARRAY['2국04-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C6','kor',1,1,'u2',8,'바른 자세로 발표하기 — 눈은 듣는 사람을 바라보고, 허리는 곧게, 손은 자연스럽게, 다리는 어깨너비로, 목소리는 알맞은 크기로 또박또박 말하며 자기소개하기',ARRAY['2국01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C7','kor',1,1,'u2',10,'집중해 듣기 — 말하는 사람을 바라보고 귀를 기울이며 바르게 앉아(허리·손·다리) 끝까지 듣고, 들은 내용(누가·무엇을·어디서)을 떠올리기',ARRAY['2국01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u2-C8','kor',1,1,'u2',12,'받침을 넣어 낱말 완성하기 — 그림이 뜻하는 낱말을 떠올려 빠진 받침을 골라 넣고, 소리가 비슷하거나 뜻 없는 받침을 넣지 않기',ARRAY['2국04-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X01','kor',1,'u2',ARRAY['K1-1-u2-C1']::text[],'받침이 있는 글자와 없는 글자를 가르지 못한다(글자 아래쪽이 비었는지 보지 않는다)','글자 아래쪽을 손가락으로 가려 보기 — 가린 곳에 자음자가 숨어 있으면 받침이 있는 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X02','kor',1,'u2',ARRAY['K1-1-u2-C2','K1-1-u2-C3']::text[],'받침을 글자 옆(오른쪽)에 따로 쓰거나 둔다(사ㄴ)','받침은 「글자의 신발」 — 늘 맨 아래에 신겨요. 글자 칸 아래쪽에 작은 네모를 그리고 거기에 받침 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X03','kor',1,'u2',ARRAY['K1-1-u2-C1','K1-1-u2-C2','K1-1-u2-C8']::text[],'글자 맨 앞(위쪽)의 첫 자음자와 아래쪽 받침을 헷갈린다','첫 자음자는 첫소리, 받침은 끝소리 — 「곰」을 천천히 읽으며 처음 소리와 끝 소리를 따로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X04','kor',1,'u2',ARRAY['K1-1-u2-C3','K1-1-u2-C4','K1-1-u2-C8']::text[],'받침을 빼고 읽거나 쓴다(산 → 사, 낙타 → 나타)','글자를 읽고 나서 입 모양이 어떻게 끝나는지 거울로 보기 — 받침 소리까지 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X05','kor',1,'u2',ARRAY['K1-1-u2-C4','K1-1-u2-C5','K1-1-u2-C8']::text[],'소리가 비슷한 받침을 헷갈린다(ㄴ ↔ ㅇ, ㅁ ↔ ㅂ, ㄹ ↔ ㄴ, ㄷ ↔ ㅅ, ㄱ ↔ ㅇ)','두 글자를 번갈아 읽으며 끝에서 입술·혀·코가 어떻게 되는지 견주기 — ㅁ은 입술을 다물고, ㅇ은 코에서 울려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X06','kor',1,'u2',ARRAY['K1-1-u2-C3','K1-1-u2-C5']::text[],'받침을 더하면서 모음자나 첫 자음자까지 바꾼다(사 + ㄴ → 선·잔)','받침을 더하기 전 글자를 위에 그대로 베껴 쓰고, 아래에만 받침을 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X07','kor',1,'u2',ARRAY['K1-1-u2-C2']::text[],'모음자를 받침이라고 여긴다','받침은 늘 자음자 — 주황 모음자 카드는 받침 칸에 들어가지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X08','kor',1,'u2',ARRAY['K1-1-u2-C5']::text[],'받침만 바뀌면 같은 글자·같은 뜻이라고 여긴다(박 = 반)','바·박·반·발을 한 줄로 놓고 하나씩 소리 내 읽기 — 소리가 다르면 다른 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X09','kor',1,'u2',ARRAY['K1-1-u2-C5']::text[],'받침을 바꾸라고 할 때 첫 자음자를 바꾼다','바꿀 곳은 맨 아래 칸 — 위쪽 자음자는 손가락으로 덮고 아래만 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X10','kor',1,'u2',ARRAY['K1-1-u2-C8']::text[],'뜻을 생각하지 않고 아무 받침이나 넣어 그림과 맞지 않는 낱말을 만든다','받침을 넣고 나서 「이 말이 그림과 같은가?」를 소리 내어 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X11','kor',1,'u2',ARRAY['K1-1-u2-C6']::text[],'발표할 때 듣는 사람을 보지 않거나 몸가짐이 바르지 않다(딴 곳 보기·삐딱하게 서기·손장난)','눈 · 허리 · 손 · 다리 — 네 곳을 거울 앞에서 하나씩 짚으며 서 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X12','kor',1,'u2',ARRAY['K1-1-u2-C6']::text[],'발표할 때 목소리가 너무 작거나 우물우물하고, 말이 너무 길거나 알맞지 않은 내용을 담는다','「뒷자리 친구에게도 들리게, 세 가지만」 — 이름·좋아하는 것·잘하는 것으로 짧게 연습하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X13','kor',1,'u2',ARRAY['K1-1-u2-C7']::text[],'들을 때 바르지 않은 자세로 딴짓을 한다(엎드리기·손장난·다리 흔들기·딴 곳 보기)','눈은 말하는 사람, 손은 무릎, 다리는 모으기 — 듣기 전에 몸부터 준비하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X14','kor',1,'u2',ARRAY['K1-1-u2-C7']::text[],'끝까지 듣지 않아 내용을 놓치거나 바꾸어 기억한다(누가·무엇을 바꿈, 중간에 끼어듦)','듣고 나서 「누가? 무엇을?」 두 가지를 손가락으로 세며 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X15','kor',1,'u2',ARRAY['K1-1-u2-C4']::text[],'글자를 하나하나 보지 않고 대충 짐작해 읽거나 센다','손가락으로 글자 하나하나를 짚으며 읽고, 받침에는 작은 점을 찍기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u2-X16','kor',1,'u2',ARRAY['K1-1-u2-C5']::text[],'받침이 같으면 자음자·모음자가 달라도 같은 글자라고 여긴다(강 = 공)','받침 ㅇ 글자들을 한 줄로 놓고 위쪽 자음자·모음자에 동그라미 — 위가 다르면 다른 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#1','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',1,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"상","correct":true},{"t":"사","mis":"K1-1-u2-X01"},{"t":"자","mis":"K1-1-u2-X01"}],"explanation":["「상」은 아래쪽에 받침 ㅇ이 있어요.","「사」·「자」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#2','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',1,'mc','auto','받침이 없는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":2,"kind":"mc","stem":"받침이 없는 글자는 어느 것인가요?","options":[{"t":"코","correct":true},{"t":"콩","mis":"K1-1-u2-X01"},{"t":"강","mis":"K1-1-u2-X01"}],"explanation":["「코」는 아래쪽이 비어 있어요.","「콩」·「강」은 아래쪽에 받침이 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"},"neg":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#3','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',1,'mc','auto','글자 아래쪽에 붙는 자음자를 무엇이라고 하나요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],true,'{"seq":3,"concept":"K1-1-u2-C1","difficulty":1,"kind":"mc","stem":"글자 아래쪽에 붙는 자음자를 무엇이라고 하나요?","options":[{"t":"받침","correct":true},{"t":"모음자","mis":"K1-1-u2-X07"},{"t":"첫 자음자","mis":"K1-1-u2-X03"}],"explanation":["글자 아래쪽에 있는 자음자를 받침이라고 해요.","모음자는 ㅏ·ㅗ처럼 막대 모양이고, 첫 자음자는 맨 앞(위쪽)에 있어요.","「잠」의 ㅁ, 「콩」의 ㅇ이 받침이에요."],"variant_rule":{"alt":[{"stem":"「잠」에서 아래쪽에 있는 ㅁ을 무엇이라고 하나요?","options":[{"t":"받침","correct":true},{"t":"모음자","mis":"K1-1-u2-X07"},{"t":"첫 자음자","mis":"K1-1-u2-X03"}],"explanation":["「잠」 아래쪽의 ㅁ은 받침이에요.","첫 자음자는 위쪽의 ㅈ이에요.","받침은 글자 아래쪽 자음자예요."]},{"stem":"「콩」에서 아래쪽에 있는 ㅇ을 무엇이라고 하나요?","options":[{"t":"받침","correct":true},{"t":"모음자","mis":"K1-1-u2-X07"},{"t":"첫 자음자","mis":"K1-1-u2-X03"}],"explanation":["「콩」 아래쪽의 ㅇ은 받침이에요.","첫 자음자는 위쪽의 ㅋ이에요.","받침은 글자 아래쪽 자음자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#4','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C3',1,'mc','auto','「자」에 받침 ㅁ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":4,"kind":"mc","stem":"「자」에 받침 ㅁ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"자","b":"ㅁ","s":null,"lay":true},"options":[{"t":"잠","correct":true},{"t":"자","mis":"K1-1-u2-X04"},{"t":"잡","mis":"K1-1-u2-X05"}],"explanation":["「자」 아래쪽에 받침 ㅁ을 더하면 「잠」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「잠」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#5','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',2,'ox','auto','「사자」와 「상장」은 소리가 같아요.',ARRAY['K1-1-u2-X04']::text[],true,'{"seq":5,"concept":"K1-1-u2-C1","difficulty":2,"kind":"ox","stem":"「사자」와 「상장」은 소리가 같아요.","answer":"X","reason_options":[{"t":"「상장」에는 받침 ㅇ이 있어서 끝소리가 달라지니까","correct":true},{"t":"받침은 모양만 있고 소리는 없으니까","mis":"K1-1-u2-X04"}],"mis":"K1-1-u2-X04","explanation":["「사자」에는 받침이 없고, 「상장」에는 글자마다 받침 ㅇ이 있어요.","받침이 있으면 끝소리가 코에서 울려요.","받침 소리까지 읽으면 두 낱말은 소리가 달라요."],"variant_rule":{"alt":[{"stem":"「나비」와 「낭비」는 소리가 같아요.","answer":"X","reason_options":[{"t":"「낭비」의 「낭」에는 받침 ㅇ이 있어서 끝소리가 달라지니까","correct":true},{"t":"받침은 모양만 있고 소리는 없으니까","mis":"K1-1-u2-X04"}],"explanation":["「나」와 「낭」은 받침 ㅇ 하나가 달라요.","받침이 있으면 끝소리가 달라져요.","받침 소리까지 끝까지 읽어요."]},{"stem":"「고기」와 「공기」는 소리가 같아요.","answer":"X","reason_options":[{"t":"「공기」의 「공」에는 받침 ㅇ이 있어서 끝소리가 달라지니까","correct":true},{"t":"받침은 모양만 있고 소리는 없으니까","mis":"K1-1-u2-X04"}],"explanation":["「고」와 「공」은 받침 ㅇ 하나가 달라요.","받침이 있으면 끝소리가 달라져요.","받침 소리까지 끝까지 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#6','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C3',2,'mc','auto','「코」에 받침 ㅇ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":6,"kind":"mc","stem":"「코」에 받침 ㅇ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"코","b":"ㅇ","s":null},"options":[{"t":"콩","correct":true},{"t":"코","mis":"K1-1-u2-X04"},{"t":"콘","mis":"K1-1-u2-X05"}],"explanation":["「코」 아래쪽에 받침 ㅇ을 더하면 「콩」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「콩」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#7','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',2,'mc','auto','받침이 있는 글자가 하나도 없는 낱말은 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":7,"concept":"K1-1-u2-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자가 하나도 없는 낱말은 어느 것인가요?","options":[{"t":"나비","correct":true},{"t":"사탕","mis":"K1-1-u2-X01"},{"t":"기린","mis":"K1-1-u2-X01"}],"explanation":["「나비」의 나·비는 아래쪽이 비어 있어요.","「사탕」의 탕, 「기린」의 린에는 받침이 있어요.","글자마다 아래쪽을 하나씩 살펴봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 있는 글자가 하나도 없는 낱말은 어느 것인가요?","options":[{"t":"모자","correct":true},{"t":"우산","mis":"K1-1-u2-X01"},{"t":"수박","mis":"K1-1-u2-X01"}],"explanation":["「모자」의 모·자는 아래쪽이 비어 있어요.","「우산」의 산, 「수박」의 박에는 받침이 있어요.","글자마다 아래쪽을 살펴봐요."]},{"stem":"이번에는 다른 보기예요. 받침이 있는 글자가 하나도 없는 낱말은 어느 것인가요?","options":[{"t":"가지","correct":true},{"t":"풍선","mis":"K1-1-u2-X01"},{"t":"거북","mis":"K1-1-u2-X01"}],"explanation":["「가지」의 가·지는 아래쪽이 비어 있어요.","「풍선」, 「거북」에는 받침이 있는 글자가 있어요.","글자마다 아래쪽을 살펴봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#8','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',2,'mc','auto','「강아지」에서 받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":8,"concept":"K1-1-u2-C1","difficulty":2,"kind":"mc","stem":"「강아지」에서 받침이 있는 글자는 어느 것인가요?","options":[{"t":"강","correct":true},{"t":"아","mis":"K1-1-u2-X01"},{"t":"지","mis":"K1-1-u2-X01"}],"explanation":["「강」은 아래쪽에 받침 ㅇ이 있어요.","「아」의 ㅇ은 위쪽 첫 자음자라 받침이 아니에요.","글자 아래쪽에 자음자가 있는지 봐요."],"variant_rule":{"alt":[{"stem":"「호랑이」에서 받침이 있는 글자는 어느 것인가요?","options":[{"t":"랑","correct":true},{"t":"호","mis":"K1-1-u2-X01"},{"t":"이","mis":"K1-1-u2-X01"}],"explanation":["「랑」은 아래쪽에 받침 ㅇ이 있어요.","「이」의 ㅇ은 위쪽 첫 자음자예요.","글자 아래쪽을 봐요."]},{"stem":"「다람쥐」에서 받침이 있는 글자는 어느 것인가요?","options":[{"t":"람","correct":true},{"t":"다","mis":"K1-1-u2-X01"},{"t":"쥐","mis":"K1-1-u2-X01"}],"explanation":["「람」은 아래쪽에 받침 ㅁ이 있어요.","「다」·「쥐」는 아래쪽이 비어 있어요.","글자 아래쪽을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#9','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C7',2,'mc','auto','선생님 말씀을 들을 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u2-X13']::text[],true,'{"seq":9,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"선생님 말씀을 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"말하는 사람을 바라보며 바르게 앉아요","correct":true},{"t":"책상에 엎드려서 들어요","mis":"K1-1-u2-X13"},{"t":"짝과 이야기하면서 들어요","mis":"K1-1-u2-X13"}],"explanation":["말하는 사람을 바라보면 말이 더 잘 들려요.","엎드리거나 다른 이야기를 하면 내용을 놓쳐요.","듣는 자세도 이 단원에서 배워요."],"variant_rule":{"alt":[{"stem":"친구가 발표할 때 바르게 듣는 모습은 어느 것인가요?","options":[{"t":"발표하는 친구를 바라보며 조용히 들어요","correct":true},{"t":"연필을 돌리며 들어요","mis":"K1-1-u2-X13"},{"t":"뒤돌아 다른 친구를 봐요","mis":"K1-1-u2-X13"}],"explanation":["발표하는 친구를 바라보며 들어요.","손장난, 딴 곳 보기는 듣기를 방해해요.","듣는 사람의 자세가 말하는 사람을 돕지요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_basic#10','kor',1,1,'u2','L01','g1_1_kor_u2_L01_basic','lesson_basic','K1-1-u2-C1',3,'mc','auto','「곰 · 사과 · 빵 · 나무」에서 받침이 있는 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":10,"concept":"K1-1-u2-C1","difficulty":3,"kind":"mc","stem":"「곰 · 사과 · 빵 · 나무」에서 받침이 있는 글자는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-1-u2-X01"},{"t":"4개","mis":"K1-1-u2-X01"}],"explanation":["받침이 있는 글자는 「곰」과 「빵」이에요.","「사과」·「나무」의 글자는 아래쪽이 비어 있어요.","글자 하나하나 아래쪽을 짚으며 세어요."],"variant_rule":{"alt":[{"stem":"「달 · 우유 · 별 · 집」에서 받침이 있는 글자는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u2-X01"},{"t":"5개","mis":"K1-1-u2-X01"}],"explanation":["달·별·집, 세 글자에 받침이 있어요.","「우유」의 우·유는 아래쪽이 비어 있어요.","글자마다 아래쪽을 짚으며 세어요."]},{"stem":"「손 · 오이 · 문 · 배」에서 받침이 있는 글자는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"K1-1-u2-X01"},{"t":"4개","mis":"K1-1-u2-X01"}],"explanation":["손·문, 두 글자에 받침이 있어요.","「오이」의 ㅇ은 위쪽 첫 자음자라 받침이 아니에요.","글자 아래쪽만 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#1','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C3',2,'mc','auto','바 + 받침 ㅂ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X06']::text[],true,'{"seq":1,"kind":"mc","stem":"바 + 받침 ㅂ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"바","b":"ㅂ","s":null},"options":[{"t":"밥","correct":true},{"t":"바ㅂ","mis":"K1-1-u2-X02"},{"t":"법","mis":"K1-1-u2-X06"}],"explanation":["「바」 아래쪽에 받침 ㅂ을 더하면 「밥」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「밥」은 받침 ㅂ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#2','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C1',2,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":2,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"문","correct":true},{"t":"무","mis":"K1-1-u2-X01"},{"t":"누","mis":"K1-1-u2-X01"}],"explanation":["「문」은 아래쪽에 받침 ㄴ이 있어요.","「무」·「누」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":2,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#3','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C1',3,'error','auto','하린이가 받침이 있는 글자만 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#4','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C3',3,'error','auto','준우가 「사」에 받침 ㄴ을 더해 「사ㄴ」처럼 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X05','K1-1-u2-X06']::text[],true,'{"seq":4,"concept":"K1-1-u2-C3","difficulty":3,"kind":"error","stem":"준우가 「사」에 받침 ㄴ을 더해 「사ㄴ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「산」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㄴ 대신 ㅇ을 더해야 해요 — 「상」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「선」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","사 + 받침 ㄴ = 산.","옆에 따로 쓰면 한 글자가 되지 않아요."],"variant_rule":{"alt":[{"stem":"서윤이가 「무」에 받침 ㄹ을 더해 「무ㄹ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「물」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㄹ 대신 ㄴ을 더해야 해요 — 「문」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「몰」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","무 + 받침 ㄹ = 물.","옆에 따로 쓰면 한 글자가 되지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#5','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C1',3,'ox','auto','「오」는 ㅇ이 있으니 받침이 있는 글자예요.',ARRAY['K1-1-u2-X03']::text[],true,'{"seq":5,"concept":"K1-1-u2-C1","difficulty":3,"kind":"ox","stem":"「오」는 ㅇ이 있으니 받침이 있는 글자예요.","answer":"X","reason_options":[{"t":"「오」의 ㅇ은 위쪽에 있는 첫 자음자이니까","correct":true},{"t":"ㅇ은 어디에 있든 받침이니까","mis":"K1-1-u2-X03"}],"mis":"K1-1-u2-X03","explanation":["「오」 = ㅇ + ㅗ, 아래쪽은 비어 있어요.","ㅇ이 아래쪽에 오면 「옹」처럼 받침이 돼요.","자리를 보고 받침인지 가려요."],"variant_rule":{"alt":[{"stem":"「이」는 ㅇ이 있으니 받침이 있는 글자예요.","answer":"X","reason_options":[{"t":"「이」의 ㅇ은 왼쪽 위에 있는 첫 자음자이니까","correct":true},{"t":"ㅇ은 어디에 있든 받침이니까","mis":"K1-1-u2-X03"}],"explanation":["「이」 = ㅇ + ㅣ, 아래쪽은 비어 있어요.","ㅇ이 아래쪽에 오면 「잉」처럼 받침이 돼요.","자리를 보고 가려요."]},{"stem":"「공」의 아래쪽 ㅇ은 받침이에요.","answer":"O","reason_options":[{"t":"ㅇ이 글자 아래쪽에 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 받침이 될 수 없으니까","mis":"K1-1-u2-X04"}],"explanation":["「공」 = ㄱ + ㅗ + 받침 ㅇ.","아래쪽 ㅇ은 코에서 울리는 끝소리를 내요.","자리를 보고 가려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#6','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C3',3,'mc','auto','「나」에 받침 ㄱ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":6,"kind":"mc","stem":"「나」에 받침 ㄱ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"나","b":"ㄱ","s":null,"lay":true},"options":[{"t":"낙","correct":true},{"t":"나","mis":"K1-1-u2-X04"},{"t":"낭","mis":"K1-1-u2-X05"}],"explanation":["「나」 아래쪽에 받침 ㄱ을 더하면 「낙」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「낙」은 받침 ㄱ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":3,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#7','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C7',3,'mc','auto','발표하는 친구를 바라보며 들어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":7,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"발표하는 친구를 바라보며 들어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 친구가 힘이 나고, 나도 내용을 더 잘 알 수 있어서","correct":true},{"t":"선생님께 칭찬을 받기 위해서","mis":"K1-1-u2-X13"},{"t":"친구의 옷을 구경하기 위해서","mis":"K1-1-u2-X13"}],"explanation":["바라보며 들으면 말하는 친구가 존중받는 느낌이 들어요.","눈이 가는 곳에 마음도 가서 내용을 잘 알아요.","듣기는 친구를 돕는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#8','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C1',4,'mc','auto','받침이 있는 글자가 가장 많은 낱말은 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":8,"concept":"K1-1-u2-C1","difficulty":4,"kind":"mc","stem":"받침이 있는 글자가 가장 많은 낱말은 어느 것인가요?","options":[{"t":"동물원","correct":true},{"t":"고양이","mis":"K1-1-u2-X01"},{"t":"코끼리","mis":"K1-1-u2-X01"}],"explanation":["「동물원」은 동·물·원 세 글자 모두 받침이 있어요.","「고양이」는 양 하나, 「코끼리」는 하나도 없어요.","글자마다 아래쪽을 세어 견줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 있는 글자가 가장 많은 낱말은 어느 것인가요?","options":[{"t":"운동장","correct":true},{"t":"놀이터","mis":"K1-1-u2-X01"},{"t":"미끄럼틀","mis":"K1-1-u2-X01"}],"explanation":["「운동장」은 운·동·장 세 글자 모두 받침이 있어요.","「놀이터」는 놀 하나, 「미끄럼틀」은 럼·틀 둘이에요.","글자마다 세어 견줘요."]},{"stem":"이번에는 다른 보기예요. 받침이 있는 글자가 가장 많은 낱말은 어느 것인가요?","options":[{"t":"선생님","correct":true},{"t":"친구","mis":"K1-1-u2-X01"},{"t":"어머니","mis":"K1-1-u2-X01"}],"explanation":["「선생님」은 선·생·님 세 글자 모두 받침이 있어요.","「친구」는 친 하나, 「어머니」는 하나도 없어요.","글자마다 세어 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#9','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C1',4,'essay','teacher','「사자」와 「상장」을 견주어 무엇이 다른지 말하고, 받침이 무엇인지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u2-C1","difficulty":4,"kind":"essay","stem":"「사자」와 「상장」을 견주어 무엇이 다른지 말하고, 받침이 무엇인지 설명해 보세요.","answer_guide":{"answer":"예: 「상장」은 「사자」의 글자마다 아래쪽에 ㅇ이 더해졌어요. 받침은 글자 아래쪽에 들어가는 자음자예요.","scoring_points":["두 낱말에서 달라진 곳(아래쪽 ㅇ)을 찾았는가","받침이 글자 아래쪽 자음자라고 말했는가","받침 때문에 소리가 달라진다고 말했는가"]},"explanation":["달라진 곳은 아래쪽 ㅇ.","받침 = 아래쪽 자음자.","받침이 있으면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L01_challenge#10','kor',1,1,'u2','L01','g1_1_kor_u2_L01_challenge','lesson_challenge','K1-1-u2-C3',4,'sa','auto','「기」에 받침 ㄹ을 더한 글자를 쓰세요.','{}'::text[],true,'{"seq":10,"kind":"sa","stem":"「기」에 받침 ㄹ을 더한 글자를 쓰세요.","asset":{"type":"bat","base":"기","b":"ㄹ","s":null},"answer":["길"],"explanation":["「기」 아래쪽에 받침 ㄹ을 더하면 「길」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「길」은 받침 ㄹ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":4,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#1','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',1,'mc','auto','받침은 글자의 어디에 들어가나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],true,'{"seq":1,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"받침은 글자의 어디에 들어가나요?","options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u2-X02"},{"t":"위쪽","mis":"K1-1-u2-X03"}],"explanation":["받침은 글자 맨 아래쪽에 들어가요.","오른쪽에는 ㅏ·ㅓ 같은 모음자가, 위쪽에는 첫 자음자가 와요.","「창」의 ㅇ도 아래쪽에 있어요."],"variant_rule":{"alt":[{"stem":"「산」에서 받침 ㄴ은 어디에 있나요?","options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u2-X02"},{"t":"위쪽 왼쪽","mis":"K1-1-u2-X03"}],"explanation":["받침 ㄴ은 「산」의 아래쪽에 있어요.","오른쪽은 모음자 ㅏ, 위쪽 왼쪽은 첫 자음자 ㅅ 자리예요.","받침은 늘 아래쪽."]},{"stem":"「손」에서 받침 ㄴ은 어디에 있나요?","options":[{"t":"맨 아래쪽","correct":true},{"t":"ㅗ 오른쪽","mis":"K1-1-u2-X02"},{"t":"맨 위쪽","mis":"K1-1-u2-X03"}],"explanation":["받침 ㄴ은 「손」의 맨 아래쪽에 있어요.","맨 위쪽은 첫 자음자 ㅅ, 그 아래는 모음자 ㅗ예요.","받침은 늘 맨 아래쪽."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#2','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',1,'mc','auto','「창」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「창」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"창","eq":false,"lay":"blank"},"options":[{"t":"ㅇ","correct":true},{"t":"ㅊ","mis":"K1-1-u2-X03"},{"t":"ㄴ","mis":"K1-1-u2-X05"}],"explanation":["「창」은 ㅊ + ㅏ + 받침 ㅇ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅊ은 첫소리, 받침 ㅇ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#3','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C3',1,'mc','auto','「차」에 받침 ㅇ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":3,"kind":"mc","stem":"「차」에 받침 ㅇ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"차","b":"ㅇ","s":null,"lay":true},"options":[{"t":"창","correct":true},{"t":"차","mis":"K1-1-u2-X04"},{"t":"찬","mis":"K1-1-u2-X05"}],"explanation":["「차」 아래쪽에 받침 ㅇ을 더하면 「창」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「창」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#4','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',1,'mc','auto','짜임 상자처럼 ㅂ, ㅕ, 받침 ㄱ을 모으면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],true,'{"seq":4,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"짜임 상자처럼 ㅂ, ㅕ, 받침 ㄱ을 모으면 어떤 글자가 되나요?","options":[{"t":"벽","correct":true},{"t":"별","mis":"K1-1-u2-X05"},{"t":"벼","mis":"K1-1-u2-X04"}],"explanation":["ㅂ + ㅕ + 받침 ㄱ = 벽.","「별」은 받침이 ㄹ, 「벼」는 받침이 없어요.","위쪽 자음자·모음자에 아래쪽 받침을 붙여요."],"asset":{"type":"bat","c":"ㅂ","v":"ㅕ","b":"ㄱ","s":null,"lay":true},"variant_rule":{"alt":[{"stem":"짜임 상자처럼 ㄱ, ㅗ, 받침 ㅇ을 모으면 어떤 글자가 되나요?","options":[{"t":"공","correct":true},{"t":"곤","mis":"K1-1-u2-X05"},{"t":"고","mis":"K1-1-u2-X04"}],"explanation":["ㄱ + ㅗ + 받침 ㅇ = 공.","「곤」은 받침이 ㄴ, 「고」는 받침이 없어요.","위쪽에 아래쪽 받침을 붙여요."],"asset":{"type":"bat","c":"ㄱ","v":"ㅗ","b":"ㅇ","s":null,"lay":true}},{"stem":"짜임 상자처럼 ㄴ, ㅜ, 받침 ㄴ을 모으면 어떤 글자가 되나요?","options":[{"t":"눈","correct":true},{"t":"눙","mis":"K1-1-u2-X05"},{"t":"누","mis":"K1-1-u2-X04"}],"explanation":["ㄴ + ㅜ + 받침 ㄴ = 눈.","「눙」은 받침이 ㅇ, 「누」는 받침이 없어요.","위쪽에 아래쪽 받침을 붙여요."],"asset":{"type":"bat","c":"ㄴ","v":"ㅜ","b":"ㄴ","s":null,"lay":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#5','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',2,'mc','auto','「벽」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":5,"kind":"mc","stem":"「벽」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"벽","eq":false},"options":[{"t":"ㄱ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X03"},{"t":"ㅇ","mis":"K1-1-u2-X05"}],"explanation":["「벽」은 ㅂ + ㅕ + 받침 ㄱ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄱ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#6','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',2,'mc','auto','「산」을 세 부분으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],true,'{"seq":6,"concept":"K1-1-u2-C2","difficulty":2,"kind":"mc","stem":"「산」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㅅ + ㅏ + 받침 ㄴ","correct":true},{"t":"ㅅ + ㄴ + 받침 ㅏ","mis":"K1-1-u2-X07"},{"t":"ㄴ + ㅏ + 받침 ㅅ","mis":"K1-1-u2-X03"}],"explanation":["「산」은 첫 자음자 ㅅ, 모음자 ㅏ, 받침 ㄴ이에요.","모음자는 받침이 될 수 없고, 첫 자음자와 받침은 자리가 달라요.","위쪽부터 차례로 나누어요."],"variant_rule":{"alt":[{"stem":"「곰」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㄱ + ㅗ + 받침 ㅁ","correct":true},{"t":"ㄱ + ㅁ + 받침 ㅗ","mis":"K1-1-u2-X07"},{"t":"ㅁ + ㅗ + 받침 ㄱ","mis":"K1-1-u2-X03"}],"explanation":["「곰」은 ㄱ, ㅗ, 받침 ㅁ이에요.","모음자 ㅗ는 받침이 아니에요.","위쪽부터 차례로."]},{"stem":"「집」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㅈ + ㅣ + 받침 ㅂ","correct":true},{"t":"ㅈ + ㅂ + 받침 ㅣ","mis":"K1-1-u2-X07"},{"t":"ㅂ + ㅣ + 받침 ㅈ","mis":"K1-1-u2-X03"}],"explanation":["「집」은 ㅈ, ㅣ, 받침 ㅂ이에요.","모음자 ㅣ는 받침이 아니에요.","위쪽부터 차례로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#7','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C3',2,'mc','auto','「사」에 받침 ㄴ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X02']::text[],true,'{"seq":7,"kind":"mc","stem":"「사」에 받침 ㄴ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"사","b":"ㄴ","s":null},"options":[{"t":"산","correct":true},{"t":"사","mis":"K1-1-u2-X04"},{"t":"사ㄴ","mis":"K1-1-u2-X02"}],"explanation":["「사」 아래쪽에 받침 ㄴ을 더하면 「산」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「산」은 받침 ㄴ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","side":"X02"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#8','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C3',2,'mc','auto','비 + 받침 ㅅ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X06']::text[],true,'{"seq":8,"kind":"mc","stem":"비 + 받침 ㅅ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"비","b":"ㅅ","s":null},"options":[{"t":"빗","correct":true},{"t":"빋","mis":"K1-1-u2-X05"},{"t":"핏","mis":"K1-1-u2-X06"}],"explanation":["「비」 아래쪽에 받침 ㅅ을 더하면 「빗」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「빗」은 받침 ㅅ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"near":"X05","cons":"X06"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ","ㅅ"],"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#9','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',2,'ox','auto','「무」에 받침 ㄹ을 더한 「물」에서 ㄹ은 ㅜ 아래에 들어가요.',ARRAY['K1-1-u2-X02']::text[],true,'{"seq":9,"concept":"K1-1-u2-C2","difficulty":2,"kind":"ox","stem":"「무」에 받침 ㄹ을 더한 「물」에서 ㄹ은 ㅜ 아래에 들어가요.","answer":"O","reason_options":[{"t":"받침은 글자 맨 아래쪽에 들어가니까","correct":true},{"t":"받침은 모음자 오른쪽에 들어가니까","mis":"K1-1-u2-X02"}],"mis":"K1-1-u2-X02","explanation":["「물」 = ㅁ + ㅜ + 받침 ㄹ.","ㅜ 아래, 맨 아래쪽이 받침 자리예요.","받침은 늘 아래쪽."],"variant_rule":{"alt":[{"stem":"「가」에 받침 ㅁ을 더한 「감」에서 ㅁ은 ㅏ 오른쪽에 들어가요.","answer":"X","reason_options":[{"t":"받침은 글자 맨 아래쪽에 들어가니까","correct":true},{"t":"ㅏ는 옆으로 서는 모음자라 받침도 옆에 오니까","mis":"K1-1-u2-X02"}],"explanation":["「감」 = ㄱ + ㅏ + 받침 ㅁ.","받침 ㅁ은 ㄱ·ㅏ 아래쪽에 들어가요.","모음자가 옆에 서도 받침은 아래."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_basic#10','kor',1,1,'u2','L03','g1_1_kor_u2_L03_basic','lesson_basic','K1-1-u2-C2',3,'mc','auto','「소」에 받침 ㅁ을 더해 「솜」을 만들었어요. 무엇이 달라졌나요?',ARRAY['K1-1-u2-X06','K1-1-u2-X03']::text[],true,'{"seq":10,"concept":"K1-1-u2-C2","difficulty":3,"kind":"mc","stem":"「소」에 받침 ㅁ을 더해 「솜」을 만들었어요. 무엇이 달라졌나요?","options":[{"t":"아래쪽에 받침 ㅁ이 생겼어요","correct":true},{"t":"모음자 ㅗ가 ㅜ로 바뀌었어요","mis":"K1-1-u2-X06"},{"t":"첫 자음자 ㅅ이 ㅁ으로 바뀌었어요","mis":"K1-1-u2-X03"}],"explanation":["소 + 받침 ㅁ = 솜.","ㅅ과 ㅗ는 그대로이고 아래쪽에 ㅁ만 생겼어요.","받침을 더해도 위쪽은 그대로예요."],"variant_rule":{"alt":[{"stem":"「비」에 받침 ㅅ을 더해 「빗」을 만들었어요. 무엇이 달라졌나요?","options":[{"t":"아래쪽에 받침 ㅅ이 생겼어요","correct":true},{"t":"모음자 ㅣ가 ㅡ로 바뀌었어요","mis":"K1-1-u2-X06"},{"t":"첫 자음자 ㅂ이 ㅅ으로 바뀌었어요","mis":"K1-1-u2-X03"}],"explanation":["비 + 받침 ㅅ = 빗.","ㅂ과 ㅣ는 그대로예요.","받침을 더해도 위쪽은 그대로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#1','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C2',2,'mc','auto','「옷」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":1,"kind":"mc","stem":"「옷」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"옷","eq":false},"options":[{"t":"ㅅ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X03"},{"t":"ㄷ","mis":"K1-1-u2-X05"}],"explanation":["「옷」은 ㅇ + ㅗ + 받침 ㅅ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅇ은 첫소리, 받침 ㅅ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ","ㅅ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#2','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C3',2,'mc','auto','「무」에 받침 ㄹ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X06']::text[],true,'{"seq":2,"kind":"mc","stem":"「무」에 받침 ㄹ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"무","b":"ㄹ","s":null},"options":[{"t":"물","correct":true},{"t":"문","mis":"K1-1-u2-X05"},{"t":"몰","mis":"K1-1-u2-X06"}],"explanation":["「무」 아래쪽에 받침 ㄹ을 더하면 「물」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「물」은 받침 ㄹ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"near":"X05","flip":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#3','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C2',3,'error','auto','서윤이가 「곰」을 나누어 「ㄱ + ㅁ + 받침 ㅗ」이라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":3,"concept":"K1-1-u2-C2","difficulty":3,"kind":"error","stem":"서윤이가 「곰」을 나누어 「ㄱ + ㅁ + 받침 ㅗ」이라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"모음자 ㅗ를 받침이라고 했어요 — ㄱ + ㅗ + 받침 ㅁ","correct":true,"mis_target":"K1-1-u2-X07"},{"t":"첫 자음자 ㄱ을 받침이라고 해야 해요","mis":"K1-1-u2-X03"},{"t":"받침은 ㅁ이 아니라 ㅂ이에요","mis":"K1-1-u2-X05"}],"explanation":["받침은 늘 자음자예요.","「곰」 = ㄱ + ㅗ + 받침 ㅁ.","모음자 ㅗ는 가운데에 있어요."],"variant_rule":{"alt":[{"stem":"지안이가 「달」을 나누어 「ㄹ + ㅏ + 받침 ㄷ」이라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"첫 자음자와 받침을 바꾸어 말했어요 — ㄷ + ㅏ + 받침 ㄹ","correct":true,"mis_target":"K1-1-u2-X03"},{"t":"ㅏ를 받침이라고 해야 해요","mis":"K1-1-u2-X07"},{"t":"받침은 ㄹ이 아니라 ㄴ이에요","mis":"K1-1-u2-X05"}],"explanation":["「달」의 첫 자음자는 ㄷ, 받침은 ㄹ이에요.","첫 자음자는 위, 받침은 아래.","첫소리 ㄷ, 끝소리 ㄹ."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#4','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C3',3,'mc','auto','「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X02']::text[],true,'{"seq":4,"kind":"mc","stem":"「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"고","b":"ㅁ","s":null,"lay":true},"options":[{"t":"곰","correct":true},{"t":"곱","mis":"K1-1-u2-X05"},{"t":"고ㅁ","mis":"K1-1-u2-X02"}],"explanation":["「고」 아래쪽에 받침 ㅁ을 더하면 「곰」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「곰」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":3,"variant_rule":{"bat":{"ask":"add","mis":{"near":"X05","side":"X02"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#5','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C2',3,'mc','auto','받침 자리를 바르게 말한 친구는 누구인가요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],true,'{"seq":5,"concept":"K1-1-u2-C2","difficulty":3,"kind":"mc","stem":"받침 자리를 바르게 말한 친구는 누구인가요?","options":[{"t":"민호: 「산」도 「손」도 받침 ㄴ은 맨 아래쪽에 있어","correct":true},{"t":"다은: 「산」은 받침이 오른쪽, 「손」은 아래쪽에 있어","mis":"K1-1-u2-X02"},{"t":"로아: 「손」은 받침이 ㅗ 위쪽에 있어","mis":"K1-1-u2-X03"}],"explanation":["모음자가 옆에 서든(산) 아래에 쌓이든(손) 받침은 맨 아래쪽이에요.","오른쪽은 모음자 자리, 위쪽은 첫 자음자 자리예요.","받침 자리는 하나 — 맨 아래."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침 자리를 바르게 말한 친구는 누구인가요?","options":[{"t":"시우: 「감」도 「곰」도 받침 ㅁ은 맨 아래쪽에 있어","correct":true},{"t":"은솔: 「감」은 받침이 ㅏ 오른쪽에 있어","mis":"K1-1-u2-X02"},{"t":"태민: 「곰」은 받침이 맨 위쪽에 있어","mis":"K1-1-u2-X03"}],"explanation":["「감」·「곰」 모두 받침 ㅁ은 맨 아래쪽이에요.","오른쪽은 모음자, 위쪽은 첫 자음자 자리.","받침 자리는 맨 아래."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#6','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C3',3,'mc','auto','「비」에 받침을 하나 더해 머리를 빗는 물건 이름을 만들려면 어떤 받침을 더하나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],true,'{"seq":6,"concept":"K1-1-u2-C3","difficulty":3,"kind":"mc","stem":"「비」에 받침을 하나 더해 머리를 빗는 물건 이름을 만들려면 어떤 받침을 더하나요?","options":[{"t":"ㅅ","correct":true},{"t":"ㄷ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X10"}],"explanation":["비 + 받침 ㅅ = 빗.","「빋」·「빕」은 머리를 빗는 물건이 아니에요.","뜻을 생각해 받침을 골라요."],"variant_rule":{"alt":[{"stem":"「소」에 받침을 하나 더해 이불 속에 넣는 폭신한 것의 이름을 만들려면 어떤 받침을 더하나요?","options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X05"},{"t":"ㄱ","mis":"K1-1-u2-X10"}],"explanation":["소 + 받침 ㅁ = 솜.","「솝」·「속」은 이불 속 폭신한 것이 아니에요.","뜻을 생각해 골라요."]},{"stem":"「차」에 받침을 하나 더해 바깥을 내다보는 곳의 이름을 만들려면 어떤 받침을 더하나요?","options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u2-X05"},{"t":"ㅁ","mis":"K1-1-u2-X10"}],"explanation":["차 + 받침 ㅇ = 창.","「찬」·「참」은 창문의 「창」이 아니에요.","뜻을 생각해 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#7','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C2',3,'match','auto','글자와 그 글자의 받침을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u2-C2","difficulty":3,"kind":"match","stem":"글자와 그 글자의 받침을 바르게 이으세요.","pairs":[{"l":"창","r":"ㅇ"},{"l":"산","r":"ㄴ"},{"l":"물","r":"ㄹ"}],"mis":"K1-1-u2-X03","explanation":["창의 받침 ㅇ, 산의 받침 ㄴ, 물의 받침 ㄹ.","받침은 아래쪽 자음자예요.","첫 자음자와 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자와 그 글자의 받침을 바르게 이으세요.","pairs":[{"l":"곰","r":"ㅁ"},{"l":"집","r":"ㅂ"},{"l":"벽","r":"ㄱ"}],"explanation":["곰-ㅁ, 집-ㅂ, 벽-ㄱ.","받침은 아래쪽 자음자.","첫 자음자와 헷갈리지 않아요."]},{"stem":"이번에는 다른 보기예요. 글자와 그 글자의 받침을 바르게 이으세요.","pairs":[{"l":"빗","r":"ㅅ"},{"l":"눈","r":"ㄴ"},{"l":"공","r":"ㅇ"}],"explanation":["빗-ㅅ, 눈-ㄴ, 공-ㅇ.","받침은 아래쪽 자음자.","「눈」은 첫 자음자도 받침도 ㄴ이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#8','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C3',4,'sa','auto','「바」에 받침 ㅇ을 더한 글자를 쓰세요.','{}'::text[],true,'{"seq":8,"kind":"sa","stem":"「바」에 받침 ㅇ을 더한 글자를 쓰세요.","asset":{"type":"bat","base":"바","b":"ㅇ","s":null},"answer":["방"],"explanation":["「바」 아래쪽에 받침 ㅇ을 더하면 「방」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「방」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":4,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#9','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C2',4,'essay','teacher','「차」와 「창」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u2-C2","difficulty":4,"kind":"essay","stem":"「차」와 「창」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.","answer_guide":{"answer":"예: 「창」은 「차」의 아래쪽에 받침 ㅇ이 들어갔어요. 끝소리가 코에서 울리게 달라졌어요.","scoring_points":["받침이 아래쪽에 들어갔다고 말했는가","받침 ㅇ을 바르게 찾았는가","소리가 달라졌다고 말했는가"]},"explanation":["받침 자리는 아래쪽.","받침은 ㅇ.","받침이 생기면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L03_challenge#10','kor',1,1,'u2','L03','g1_1_kor_u2_L03_challenge','lesson_challenge','K1-1-u2-C3',4,'mc','auto','「낙타」를 「나타」로 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":10,"concept":"K1-1-u2-C3","difficulty":4,"kind":"mc","stem":"「낙타」를 「나타」로 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"받침 ㄱ 소리까지 끝까지 내어 「낙」이라고 읽어요","correct":true},{"t":"받침은 모양만 있으니 안 읽어도 돼요","mis":"K1-1-u2-X04"},{"t":"「낙」은 「낭」과 같은 소리로 읽어요","mis":"K1-1-u2-X05"}],"explanation":["「낙」에는 받침 ㄱ이 있어요.","받침 소리를 빼면 다른 말이 돼요.","끝소리가 짧게 닫히도록 읽어요."],"variant_rule":{"alt":[{"stem":"「약국」을 「야국」으로 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"받침 ㄱ 소리까지 끝까지 내어 「약」이라고 읽어요","correct":true},{"t":"받침은 모양만 있으니 안 읽어도 돼요","mis":"K1-1-u2-X04"},{"t":"「약」은 「양」과 같은 소리로 읽어요","mis":"K1-1-u2-X05"}],"explanation":["「약」에는 받침 ㄱ이 있어요.","받침 소리를 빼면 다른 말이 돼요.","끝소리까지 읽어요."]},{"stem":"「연필」을 「여필」로 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"받침 ㄴ 소리까지 끝까지 내어 「연」이라고 읽어요","correct":true},{"t":"받침은 모양만 있으니 안 읽어도 돼요","mis":"K1-1-u2-X04"},{"t":"「연」은 「영」과 같은 소리로 읽어요","mis":"K1-1-u2-X05"}],"explanation":["「연」에는 받침 ㄴ이 있어요.","받침 소리를 빼면 다른 말이 돼요.","끝소리까지 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#1','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',1,'match','auto','받침과 그 받침이 들어간 낱말을 바르게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"K1-1-u2-C4","difficulty":1,"kind":"match","stem":"받침과 그 받침이 들어간 낱말을 바르게 이으세요.","pairs":[{"l":"받침 ㄱ","r":"약국"},{"l":"받침 ㄹ","r":"별"},{"l":"받침 ㅂ","r":"집"}],"mis":"K1-1-u2-X05","explanation":["약국의 ㄱ, 별의 ㄹ, 집의 ㅂ.","받침은 글자 아래쪽에서 찾아요.","받침마다 끝소리가 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침과 그 받침이 들어간 낱말을 바르게 이으세요.","pairs":[{"l":"받침 ㄴ","r":"손"},{"l":"받침 ㅁ","r":"봄"},{"l":"받침 ㅇ","r":"빵"}],"explanation":["손의 ㄴ, 봄의 ㅁ, 빵의 ㅇ.","받침은 아래쪽에서 찾아요.","ㄴ·ㅇ은 소리가 비슷해도 모양이 달라요."]},{"stem":"이번에는 다른 보기예요. 받침과 그 받침이 들어간 낱말을 바르게 이으세요.","pairs":[{"l":"받침 ㄷ","r":"곧"},{"l":"받침 ㄱ","r":"박수"},{"l":"받침 ㅁ","r":"감"}],"explanation":["곧의 ㄷ, 박의 ㄱ, 감의 ㅁ.","받침은 아래쪽에서 찾아요.","받침 ㄷ은 자주 만나지 않아도 모양을 기억해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#2','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',1,'mc','auto','「달」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「달」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"달","eq":false},"options":[{"t":"ㄹ","correct":true},{"t":"ㄷ","mis":"K1-1-u2-X03"},{"t":"ㄴ","mis":"K1-1-u2-X05"}],"explanation":["「달」은 ㄷ + ㅏ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄷ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#3','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C5',1,'mc','auto','「반」의 받침 ㄴ을 ㅁ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":3,"kind":"mc","stem":"「반」의 받침 ㄴ을 ㅁ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"반","eq":false},"options":[{"t":"밤","correct":true},{"t":"만","mis":"K1-1-u2-X09"},{"t":"반","mis":"K1-1-u2-X08"}],"explanation":["「반」에서 받침 ㄴ 자리에 ㅁ을 넣으면 「밤」이에요.","맨 앞 자음자 ㅂ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":1,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#4','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',1,'mc','auto','끝소리에서 입술을 꼭 다무는 받침 ㅁ이 들어간 글자는 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],true,'{"seq":4,"concept":"K1-1-u2-C4","difficulty":1,"kind":"mc","stem":"끝소리에서 입술을 꼭 다무는 받침 ㅁ이 들어간 글자는 어느 것인가요?","options":[{"t":"곰","correct":true},{"t":"공","mis":"K1-1-u2-X05"},{"t":"곤","mis":"K1-1-u2-X05"}],"explanation":["「곰」은 받침 ㅁ — 끝에서 입술을 다물어요.","「공」은 ㅇ(코에서 울림), 「곤」은 ㄴ이에요.","끝소리의 입 모양을 견줘요."],"variant_rule":{"alt":[{"stem":"끝소리가 코에서 길게 울리는 받침 ㅇ이 들어간 글자는 어느 것인가요?","options":[{"t":"빵","correct":true},{"t":"빤","mis":"K1-1-u2-X05"},{"t":"빰","mis":"K1-1-u2-X05"}],"explanation":["「빵」은 받침 ㅇ — 코에서 울려요.","「빤」은 ㄴ, 「빰」은 ㅁ이에요.","끝소리를 견줘요."]},{"stem":"입술을 한 번 톡 닫으며 끝나는 받침 ㅂ이 들어간 글자는 어느 것인가요?","options":[{"t":"밥","correct":true},{"t":"밤","mis":"K1-1-u2-X05"},{"t":"반","mis":"K1-1-u2-X05"}],"explanation":["「밥」은 받침 ㅂ — 입술을 톡 닫아요.","「밤」은 ㅁ, 「반」은 ㄴ이에요.","ㅁ과 ㅂ은 입술이 닫히는 느낌이 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#5','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C5',2,'mc','auto','「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X08','K1-1-u2-X04']::text[],true,'{"seq":5,"kind":"mc","stem":"「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"곰","eq":false},"options":[{"t":"공","correct":true},{"t":"곰","mis":"K1-1-u2-X08"},{"t":"고","mis":"K1-1-u2-X04"}],"explanation":["「곰」에서 받침 ㅁ 자리에 ㅇ을 넣으면 「공」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅗ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"keep":"X08","drop":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#6','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',2,'mc','auto','「낙타」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":6,"concept":"K1-1-u2-C4","difficulty":2,"kind":"mc","stem":"「낙타」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[낙타]","correct":true},{"t":"[나타]","mis":"K1-1-u2-X04"},{"t":"[낭타]","mis":"K1-1-u2-X05"}],"explanation":["「낙」의 받침 ㄱ 소리까지 읽어요.","받침을 빼거나(나타) 다른 받침으로(낭타) 읽으면 안 돼요.","끝소리가 짧게 닫혀요."],"variant_rule":{"alt":[{"stem":"「약국」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[약꾹]","correct":true},{"t":"[야국]","mis":"K1-1-u2-X04"},{"t":"[양국]","mis":"K1-1-u2-X05"}],"explanation":["「약」의 받침 ㄱ 소리까지 읽어요.","받침을 빼거나 다른 받침으로 읽지 않아요.","ㄱ 뒤 ㄱ은 조금 세게 [약꾹]으로 들려요."]},{"stem":"「연필」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[연필]","correct":true},{"t":"[여필]","mis":"K1-1-u2-X04"},{"t":"[영필]","mis":"K1-1-u2-X05"}],"explanation":["「연」의 받침 ㄴ 소리까지 읽어요.","받침을 빼거나 ㅇ으로 바꿔 읽지 않아요.","ㄴ은 혀가 윗니 뒤에 닿아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#7','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C5',2,'mc','auto','「바」에 받침만 붙여 만든 글자를 바르게 모은 것은 어느 것인가요?',ARRAY['K1-1-u2-X06']::text[],true,'{"seq":7,"concept":"K1-1-u2-C5","difficulty":2,"kind":"mc","stem":"「바」에 받침만 붙여 만든 글자를 바르게 모은 것은 어느 것인가요?","options":[{"t":"박 · 반 · 발","correct":true},{"t":"박 · 보 · 발","mis":"K1-1-u2-X06"},{"t":"밥 · 파 · 방","mis":"K1-1-u2-X06"}],"explanation":["박·반·발은 「바」 아래에 받침만 붙였어요.","「보」는 모음자, 「파」는 첫 자음자가 바뀌었어요.","받침만 바꾸면 위쪽 「바」는 그대로예요."],"variant_rule":{"alt":[{"stem":"「고」에 받침만 붙여 만든 글자를 바르게 모은 것은 어느 것인가요?","options":[{"t":"곰 · 공 · 곧","correct":true},{"t":"곰 · 굼 · 곧","mis":"K1-1-u2-X06"},{"t":"공 · 콩 · 곰","mis":"K1-1-u2-X06"}],"explanation":["곰·공·곧은 「고」 아래에 받침만 붙였어요.","「굼」은 모음자, 「콩」은 첫 자음자가 바뀌었어요.","위쪽 「고」는 그대로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#8','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',2,'mc','auto','「가」에 받침 ㄴ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":8,"kind":"mc","stem":"「가」에 받침 ㄴ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"가","b":"ㄴ","s":null},"options":[{"t":"간","correct":true},{"t":"가","mis":"K1-1-u2-X04"},{"t":"강","mis":"K1-1-u2-X05"}],"explanation":["「가」 아래쪽에 받침 ㄴ을 더하면 「간」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「간」은 받침 ㄴ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#9','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C5',2,'ox','auto','「박」과 「밤」은 받침만 다르니 뜻이 같아요.',ARRAY['K1-1-u2-X08']::text[],true,'{"seq":9,"concept":"K1-1-u2-C5","difficulty":2,"kind":"ox","stem":"「박」과 「밤」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"mis":"K1-1-u2-X08","explanation":["「박」은 박수의 박, 「밤」은 깜깜한 밤이에요.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."],"variant_rule":{"alt":[{"stem":"「달」과 「담」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"explanation":["「달」은 밤하늘의 달, 「담」은 집 둘레의 담이에요.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_basic#10','kor',1,1,'u2','L05','g1_1_kor_u2_L05_basic','lesson_basic','K1-1-u2-C4',3,'error','auto','시우가 「약국에 갔어요.」를 「야국에 갔어요.」라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":10,"concept":"K1-1-u2-C4","difficulty":3,"kind":"error","stem":"시우가 「약국에 갔어요.」를 「야국에 갔어요.」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「약」의 받침 ㄱ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「국」의 받침을 ㅇ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「약」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「약」에는 받침 ㄱ이 있어요.","「국」과 첫 자음자는 바르게 읽었어요.","받침 소리까지 끝까지."],"variant_rule":{"alt":[{"stem":"은솔이가 「달님이 웃어요.」를 「다님이 웃어요.」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「달」의 받침 ㄹ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「님」의 받침을 ㄴ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「달」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「달」에는 받침 ㄹ이 있어요.","「님」과 첫 자음자는 바르게 읽었어요.","받침 소리까지 끝까지."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#1','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C5',2,'mc','auto','「산」의 받침 ㄴ을 ㄹ로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":1,"kind":"mc","stem":"「산」의 받침 ㄴ을 ㄹ로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"산","eq":false},"options":[{"t":"살","correct":true},{"t":"란","mis":"K1-1-u2-X09"},{"t":"산","mis":"K1-1-u2-X08"}],"explanation":["「산」에서 받침 ㄴ 자리에 ㄹ을 넣으면 「살」이에요.","맨 앞 자음자 ㅅ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#2','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C4',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"곰","at":0,"pic":"🐻"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X05"},{"t":"ㄱ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「곰」이에요.","「고」에 받침 ㅁ을 넣어야 「곰」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#3','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C5',3,'mc','auto','「바」에 받침을 붙여 「해가 지고 깜깜한 때」를 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],true,'{"seq":3,"concept":"K1-1-u2-C5","difficulty":3,"kind":"mc","stem":"「바」에 받침을 붙여 「해가 지고 깜깜한 때」를 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㅁ — 「밤」","correct":true},{"t":"받침 ㅂ — 「밥」","mis":"K1-1-u2-X05"},{"t":"받침 ㅇ — 「방」","mis":"K1-1-u2-X10"}],"explanation":["바 + 받침 ㅁ = 밤.","「밥」은 먹는 것, 「방」은 집 안의 방이에요.","받침이 바뀌면 뜻이 바뀌어요."],"variant_rule":{"alt":[{"stem":"「바」에 받침을 붙여 「걸을 때 쓰는 몸의 한 부분」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㄹ — 「발」","correct":true},{"t":"받침 ㄴ — 「반」","mis":"K1-1-u2-X05"},{"t":"받침 ㄱ — 「박」","mis":"K1-1-u2-X10"}],"explanation":["바 + 받침 ㄹ = 발.","「반」·「박」은 걸을 때 쓰는 몸이 아니에요.","뜻을 생각해 받침을 골라요."]},{"stem":"「바」에 받침을 붙여 「잠자는 곳, 집 안의 칸」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㅇ — 「방」","correct":true},{"t":"받침 ㄴ — 「반」","mis":"K1-1-u2-X05"},{"t":"받침 ㅂ — 「밥」","mis":"K1-1-u2-X10"}],"explanation":["바 + 받침 ㅇ = 방.","「반」·「밥」은 집 안의 칸이 아니에요.","뜻을 생각해 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#4','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C4',3,'error','auto','다은이가 받침 소리를 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#5','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C5',3,'mc','auto','「강」의 받침 ㅇ을 ㅁ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X04']::text[],true,'{"seq":5,"kind":"mc","stem":"「강」의 받침 ㅇ을 ㅁ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"강","eq":false},"options":[{"t":"감","correct":true},{"t":"망","mis":"K1-1-u2-X09"},{"t":"가","mis":"K1-1-u2-X04"}],"explanation":["「강」에서 받침 ㅇ 자리에 ㅁ을 넣으면 「감」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":3,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","drop":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#6','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C4',3,'mc','auto','「곧」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":6,"kind":"mc","stem":"「곧」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"곧","eq":false},"options":[{"t":"ㄷ","correct":true},{"t":"ㄱ","mis":"K1-1-u2-X03"},{"t":"ㅅ","mis":"K1-1-u2-X05"}],"explanation":["「곧」은 ㄱ + ㅗ + 받침 ㄷ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄱ은 첫소리, 받침 ㄷ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":3,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#7','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C5',3,'ox','auto','「강」과 「공」은 받침이 ㅇ으로 같으니 같은 글자예요.',ARRAY['K1-1-u2-X16']::text[],true,'{"seq":7,"concept":"K1-1-u2-C5","difficulty":3,"kind":"ox","stem":"「강」과 「공」은 받침이 ㅇ으로 같으니 같은 글자예요.","answer":"X","reason_options":[{"t":"받침이 같아도 모음자가 다르면 다른 글자이니까","correct":true},{"t":"받침만 같으면 같은 소리가 나니까","mis":"K1-1-u2-X16"}],"mis":"K1-1-u2-X16","explanation":["「강」은 ㅏ, 「공」은 ㅗ — 모음자가 달라요.","받침 ㅇ을 똑같이 붙여도 위쪽이 다르면 다른 글자예요.","위쪽 자음자·모음자도 함께 봐요."],"variant_rule":{"alt":[{"stem":"「산」과 「손」은 받침이 ㄴ으로 같으니 같은 글자예요.","answer":"X","reason_options":[{"t":"받침이 같아도 모음자가 다르면 다른 글자이니까","correct":true},{"t":"받침만 같으면 같은 소리가 나니까","mis":"K1-1-u2-X16"}],"explanation":["「산」은 ㅏ, 「손」은 ㅗ — 모음자가 달라요.","받침이 같아도 다른 글자예요.","위쪽도 함께 봐요."]},{"stem":"「밤」과 「감」은 받침이 ㅁ으로 같으니 같은 글자예요.","answer":"X","reason_options":[{"t":"받침이 같아도 첫 자음자가 다르면 다른 글자이니까","correct":true},{"t":"받침만 같으면 같은 소리가 나니까","mis":"K1-1-u2-X16"}],"explanation":["「밤」은 ㅂ, 「감」은 ㄱ — 첫 자음자가 달라요.","받침이 같아도 다른 글자예요.","위쪽도 함께 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#8','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C4',4,'mc','auto','다음 글에서 받침 ㄹ이 들어간 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X15']::text[],true,'{"seq":8,"concept":"K1-1-u2-C4","difficulty":4,"kind":"mc","stem":"다음 글에서 받침 ㄹ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u2-X15"},{"t":"6개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㄹ 글자: 달 · 별 · 을 · 불.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 아래쪽을 짚으며 세요."],"asset":{"type":"passage","lines":["달님이 별을 불렀어요."]},"variant_rule":{"alt":[{"stem":"다음 글에서 받침 ㅁ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-1-u2-X15"},{"t":"4개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㅁ 글자: 엄 · 감.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["엄마랑 감을 따러 산에 갔어요."]}},{"stem":"다음 글에서 받침 ㅇ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u2-X15"},{"t":"6개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㅇ 글자: 동 · 생 · 공 · 방.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["동생이 공을 들고 방으로 왔어요."]}},{"stem":"다음 글에서 받침 ㄴ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u2-X15"},{"t":"5개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㄴ 글자: 친 · 손 · 문.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["친구가 손에 빵을 들고 문을 열었어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#9','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C5',4,'essay','teacher','「바」에 받침 ㄱ·ㄴ·ㄹ·ㅁ을 하나씩 붙여 글자 네 개를 만들고, 그 가운데 두 글자를 넣어 짧은 말을 만들어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u2-C5","difficulty":4,"kind":"essay","stem":"「바」에 받침 ㄱ·ㄴ·ㄹ·ㅁ을 하나씩 붙여 글자 네 개를 만들고, 그 가운데 두 글자를 넣어 짧은 말을 만들어 보세요.","answer_guide":{"answer":"예: 박 · 반 · 발 · 밤 — 「밤에 발을 씻어요.」","scoring_points":["받침을 바르게 붙여 네 글자를 만들었는가","두 글자를 넣어 뜻이 통하는 말을 만들었는가","받침 소리까지 또박또박 읽을 수 있는가"]},"explanation":["바 + ㄱ·ㄴ·ㄹ·ㅁ = 박·반·발·밤.","받침이 바뀌면 뜻이 바뀌어요.","짧은 말 속에서 받침까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L05_challenge#10','kor',1,1,'u2','L05','g1_1_kor_u2_L05_challenge','lesson_challenge','K1-1-u2-C4',4,'sa','auto','「별」의 받침을 쓰세요.','{}'::text[],true,'{"seq":10,"kind":"sa","stem":"「별」의 받침을 쓰세요.","asset":{"type":"bat","s":"별","eq":false},"answer":["ㄹ"],"explanation":["「별」은 ㅂ + ㅕ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":4,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#1','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',1,'mc','auto','발표할 때 눈은 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],true,'{"seq":1,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 눈은 어떻게 하나요?","options":[{"t":"듣는 친구들을 바라봐요","correct":true},{"t":"바닥을 내려다봐요","mis":"K1-1-u2-X11"},{"t":"창밖을 봐요","mis":"K1-1-u2-X11"}],"explanation":["눈으로 친구들을 바라보면 마음이 잘 전해져요.","딴 곳을 보면 듣는 친구가 서운할 수 있어요.","발표 자세 첫째 — 눈."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표할 때 눈은 어떻게 하나요?","options":[{"t":"듣는 사람 쪽을 골고루 바라봐요","correct":true},{"t":"천장을 올려다봐요","mis":"K1-1-u2-X11"},{"t":"내 신발만 봐요","mis":"K1-1-u2-X11"}],"explanation":["듣는 사람을 바라봐요.","딴 곳을 보면 듣는 사람이 서운해요.","발표 자세 — 눈."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#2','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',1,'mc','auto','발표할 때 허리는 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":2,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 허리는 어떻게 하나요?","options":[{"t":"곧게 세워요","correct":true},{"t":"삐딱하게 기대요","mis":"K1-1-u2-X11"},{"t":"앞으로 푹 숙여요","mis":"K1-1-u2-X11"}],"explanation":["허리를 곧게 세우면 목소리가 잘 나와요.","기대거나 숙이면 씩씩해 보이지 않아요.","발표 자세 — 허리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#3','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',1,'mc','auto','발표할 때 손은 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],true,'{"seq":3,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 손은 어떻게 하나요?","options":[{"t":"자연스럽게 아래로 내려요","correct":true},{"t":"옷을 만지작거려요","mis":"K1-1-u2-X11"},{"t":"주머니에 넣고 흔들어요","mis":"K1-1-u2-X11"}],"explanation":["손을 가만히 내리면 발표가 깔끔해요.","손장난을 하면 듣는 사람이 집중하기 어려워요.","발표 자세 — 손."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표할 때 손은 어떻게 하나요?","options":[{"t":"가지런히 내리거나 발표 종이를 바르게 들어요","correct":true},{"t":"머리카락을 꼬아요","mis":"K1-1-u2-X11"},{"t":"연필을 돌려요","mis":"K1-1-u2-X11"}],"explanation":["손은 가지런히.","손장난은 듣는 사람의 눈을 빼앗아요.","발표 자세 — 손."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#4','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',1,'mc','auto','발표할 때 목소리는 어떻게 하나요?',ARRAY['K1-1-u2-X12']::text[],false,'{"seq":4,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 목소리는 어떻게 하나요?","options":[{"t":"알맞은 크기로 또박또박 말해요","correct":true},{"t":"작게 우물우물 말해요","mis":"K1-1-u2-X12"},{"t":"아주 크게 소리쳐요","mis":"K1-1-u2-X12"}],"explanation":["또박또박 말하면 모두 잘 들을 수 있어요.","너무 작거나 너무 크면 듣기 힘들어요.","발표 자세 — 목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#5','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',2,'ox','auto','발표할 때 다리는 어깨너비만큼 벌리고 편안하게 서요.',ARRAY['K1-1-u2-X11']::text[],true,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":2,"kind":"ox","stem":"발표할 때 다리는 어깨너비만큼 벌리고 편안하게 서요.","answer":"O","reason_options":[{"t":"몸이 흔들리지 않아 발표가 안정되니까","correct":true},{"t":"다리를 꼬고 서야 멋있어 보이니까","mis":"K1-1-u2-X11"}],"mis":"K1-1-u2-X11","explanation":["다리를 어깨너비로 벌리면 몸이 흔들리지 않아요.","다리를 꼬거나 흔들면 듣는 사람도 불안해요.","발표 자세 — 다리."],"variant_rule":{"alt":[{"stem":"발표할 때 몸을 이리저리 흔들며 말하면 더 재미있어요.","answer":"X","reason_options":[{"t":"몸이 흔들리면 듣는 사람이 말에 집중하기 어려우니까","correct":true},{"t":"움직여야 긴장이 풀리니 계속 흔들어야 하니까","mis":"K1-1-u2-X11"}],"explanation":["몸을 흔들면 듣는 사람의 눈이 몸에 가요.","다리를 어깨너비로 벌리고 바르게 서요.","발표 자세 — 다리."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#6','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',2,'mc','auto','자기소개를 할 때 말할 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u2-X12']::text[],true,'{"seq":6,"concept":"K1-1-u2-C6","difficulty":2,"kind":"mc","stem":"자기소개를 할 때 말할 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 비밀","correct":true},{"t":"내 이름","mis":"K1-1-u2-X12"},{"t":"내가 좋아하는 음식","mis":"K1-1-u2-X12"}],"explanation":["친구의 비밀은 여러 사람 앞에서 말하지 않아요.","이름·좋아하는 것·잘하는 것은 자기소개에 알맞아요.","나를 알려 주는 내용을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자기소개를 할 때 말할 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"어제 짝과 다툰 이야기","correct":true},{"t":"내가 잘하는 것","mis":"K1-1-u2-X12"},{"t":"내가 좋아하는 놀이","mis":"K1-1-u2-X12"}],"explanation":["다툰 이야기는 나를 소개하는 말이 아니에요.","잘하는 것·좋아하는 것은 자기소개에 알맞아요.","나를 알려 주는 내용."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#7','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',2,'error','auto','지안이의 발표 모습이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#8','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',2,'mc','auto','발표할 때 딴 곳만 보면 듣는 친구는 어떤 마음이 들까요?',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":8,"concept":"K1-1-u2-C6","difficulty":2,"kind":"mc","stem":"발표할 때 딴 곳만 보면 듣는 친구는 어떤 마음이 들까요?","options":[{"t":"서운한 마음","correct":true},{"t":"고마운 마음","mis":"K1-1-u2-X11"},{"t":"신나는 마음","mis":"K1-1-u2-X11"}],"explanation":["나를 보지 않으면 서운해요.","바라봐 주면 듣는 친구도 힘이 나요.","눈은 듣는 사람에게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#9','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',2,'match','auto','몸의 부분과 발표할 때의 바른 모습을 이으세요.','{}'::text[],true,'{"seq":9,"concept":"K1-1-u2-C6","difficulty":2,"kind":"match","stem":"몸의 부분과 발표할 때의 바른 모습을 이으세요.","pairs":[{"l":"눈","r":"듣는 사람 바라보기"},{"l":"허리","r":"곧게 세우기"},{"l":"손","r":"자연스럽게 내리기"}],"mis":"K1-1-u2-X11","explanation":["눈-바라보기, 허리-곧게, 손-내리기.","다섯 가지 가운데 셋이에요.","다리와 목소리도 잊지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸의 부분과 발표할 때의 바른 모습을 이으세요.","pairs":[{"l":"다리","r":"어깨너비로 벌리기"},{"l":"목소리","r":"또박또박 알맞게"},{"l":"눈","r":"듣는 사람 바라보기"}],"explanation":["다리-어깨너비, 목소리-또박또박, 눈-바라보기.","다섯 가지 가운데 셋이에요.","허리와 손도 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_basic#10','kor',1,1,'u2','L08','g1_1_kor_u2_L08_basic','lesson_basic','K1-1-u2-C6',3,'mc','auto','자기소개를 할 때 「세 가지만」 말하자고 하는 까닭은 무엇인가요?',ARRAY['K1-1-u2-X12']::text[],false,'{"seq":10,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"자기소개를 할 때 「세 가지만」 말하자고 하는 까닭은 무엇인가요?","options":[{"t":"너무 길면 듣는 사람이 기억하기 어려워서","correct":true},{"t":"세 가지보다 많이 말하면 안 되는 규칙이 있어서","mis":"K1-1-u2-X12"},{"t":"발표는 빨리 끝내는 것이 가장 중요해서","mis":"K1-1-u2-X12"}],"explanation":["짧고 또렷해야 듣는 사람이 잘 기억해요.","이름·좋아하는 것·잘하는 것 세 가지면 충분해요.","듣는 사람을 생각해 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#1','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',2,'mc','auto','발표할 때 목소리 크기로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X12']::text[],false,'{"seq":1,"concept":"K1-1-u2-C6","difficulty":2,"kind":"mc","stem":"발표할 때 목소리 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"맨 뒷자리 친구에게도 들릴 만큼","correct":true},{"t":"옆 짝에게만 들릴 만큼","mis":"K1-1-u2-X12"},{"t":"복도까지 울릴 만큼 소리쳐서","mis":"K1-1-u2-X12"}],"explanation":["뒷자리까지 들리면 모두 들을 수 있어요.","너무 작거나 너무 크면 듣기 힘들어요.","교실 크기에 맞춰 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#2','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',2,'ox','auto','발표할 때 손을 만지작거리면 듣는 사람이 발표에 집중하기 어려워요.',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":2,"concept":"K1-1-u2-C6","difficulty":2,"kind":"ox","stem":"발표할 때 손을 만지작거리면 듣는 사람이 발표에 집중하기 어려워요.","answer":"O","reason_options":[{"t":"움직이는 손에 눈이 가서 말을 놓치니까","correct":true},{"t":"손을 움직이면 목소리가 작아지니까","mis":"K1-1-u2-X11"}],"mis":"K1-1-u2-X11","explanation":["움직이는 손은 듣는 사람의 눈을 빼앗아요.","손은 자연스럽게 내려요.","발표 자세 — 손."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#3','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',3,'mc','auto','다섯 가지 발표 자세를 모두 잘 지킨 친구는 누구인가요?',ARRAY['K1-1-u2-X12','K1-1-u2-X11']::text[],true,'{"seq":3,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"다섯 가지 발표 자세를 모두 잘 지킨 친구는 누구인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"K1-1-u2-X12"},{"t":"다","mis":"K1-1-u2-X11"}],"explanation":["「나」는 눈·허리·손·다리·목소리를 모두 지켰어요.","「가」는 목소리가 너무 작고, 「다」는 손장난을 했어요.","다섯 가지를 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["가: 친구들을 보며 허리를 펴고 섰지만 목소리가 너무 작았어요.","나: 친구들을 보며 바르게 서서 또박또박 말했어요.","다: 또박또박 말했지만 손으로 이름표를 계속 만졌어요."]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다섯 가지 발표 자세를 모두 잘 지킨 친구는 누구인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"K1-1-u2-X11"},{"t":"나","mis":"K1-1-u2-X11"}],"explanation":["「다」는 다섯 가지를 모두 지켰어요.","「가」는 바닥만 보고, 「나」는 다리를 꼬고 흔들었어요.","다섯 가지를 하나씩 짚어요."],"asset":{"type":"passage","lines":["가: 또박또박 말했지만 바닥만 내려다봤어요.","나: 친구들을 봤지만 다리를 꼬고 흔들었어요.","다: 친구들을 보며 바르게 서서 알맞은 목소리로 말했어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#4','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',3,'mc','auto','자기소개를 시작하는 첫 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X12']::text[],false,'{"seq":4,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"자기소개를 시작하는 첫 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"안녕하세요? 저는 1학년 2반 하린이에요.","correct":true},{"t":"음… 그러니까… 저기요…","mis":"K1-1-u2-X12"},{"t":"저는 당근이 싫고, 동생이 있고, 어제는 비가 왔고…","mis":"K1-1-u2-X12"}],"explanation":["인사와 이름으로 짧고 또렷하게 시작해요.","머뭇거리거나 이것저것 길게 늘어놓으면 듣기 힘들어요.","처음 한 말이 귀에 쏙 들어오게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#5','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',3,'mc','auto','서윤이는 발표할 때 친구들을 보고, 허리를 펴고, 손도 내렸어요. 그런데 목소리가 너무 작았어요. 서윤이에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X11','K1-1-u2-X12']::text[],false,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"서윤이는 발표할 때 친구들을 보고, 허리를 펴고, 손도 내렸어요. 그런데 목소리가 너무 작았어요. 서윤이에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"뒷자리 친구에게도 들리게 조금 더 크게 말해 봐","correct":true},{"t":"눈을 감고 말하면 덜 떨려","mis":"K1-1-u2-X11"},{"t":"빨리 말하고 얼른 들어가","mis":"K1-1-u2-X12"}],"explanation":["서윤이가 고칠 것은 목소리 크기예요.","눈 감기·빨리 끝내기는 도움이 안 돼요.","잘한 점은 두고 고칠 점 하나만 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#6','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',3,'error','auto','준우의 자기소개예요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#7','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',3,'ox','auto','발표할 때 허리를 곧게 세우면 목소리가 더 잘 나와요.',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":7,"concept":"K1-1-u2-C6","difficulty":3,"kind":"ox","stem":"발표할 때 허리를 곧게 세우면 목소리가 더 잘 나와요.","answer":"O","reason_options":[{"t":"몸이 펴져 숨을 크게 쉴 수 있으니까","correct":true},{"t":"허리를 펴면 키가 커 보이기 때문이니까","mis":"K1-1-u2-X11"}],"mis":"K1-1-u2-X11","explanation":["허리를 펴면 숨을 깊게 쉬어 목소리가 잘 나와요.","키를 커 보이려는 것이 아니에요.","발표 자세 — 허리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#8','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',4,'essay','teacher','나를 소개하는 말을 세 문장으로 써 보고, 발표할 때 꼭 지킬 자세 두 가지를 함께 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u2-C6","difficulty":4,"kind":"essay","stem":"나를 소개하는 말을 세 문장으로 써 보고, 발표할 때 꼭 지킬 자세 두 가지를 함께 써 보세요.","answer_guide":{"answer":"예: 「저는 하린이에요. 좋아하는 놀이는 술래잡기예요. 잘하는 것은 그림 그리기예요.」 — 친구들을 바라보기, 또박또박 말하기","scoring_points":["이름·좋아하는 것·잘하는 것 등 세 문장을 썼는가","발표 자세를 두 가지 바르게 썼는가","문장이 짧고 또렷한가"]},"explanation":["세 문장으로 짧게.","자세 두 가지.","듣는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#9','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',4,'mc','auto','준우의 발표 자세 점검표예요. 가장 먼저 연습할 것은 무엇인가요?',ARRAY['K1-1-u2-X11','K1-1-u2-X12']::text[],true,'{"seq":9,"concept":"K1-1-u2-C6","difficulty":4,"kind":"mc","stem":"준우의 발표 자세 점검표예요. 가장 먼저 연습할 것은 무엇인가요?","options":[{"t":"손을 자연스럽게 내리기","correct":true},{"t":"친구들 바라보기","mis":"K1-1-u2-X11"},{"t":"목소리 크기 맞추기","mis":"K1-1-u2-X12"}],"explanation":["점검표에서 ×는 손 하나예요.","○인 것은 이미 잘하고 있어요.","안 된 것부터 연습해요."],"asset":{"type":"passage","lines":["눈 ○ · 허리 ○ · 손 × · 다리 ○ · 목소리 ○"]},"variant_rule":{"alt":[{"stem":"로아의 발표 자세 점검표예요. 가장 먼저 연습할 것은 무엇인가요?","options":[{"t":"알맞은 크기로 또박또박 말하기","correct":true},{"t":"허리 곧게 세우기","mis":"K1-1-u2-X11"},{"t":"다리 어깨너비로 서기","mis":"K1-1-u2-X11"}],"explanation":["점검표에서 ×는 목소리 하나예요.","○인 것은 이미 잘하고 있어요.","안 된 것부터."],"asset":{"type":"passage","lines":["눈 ○ · 허리 ○ · 손 ○ · 다리 ○ · 목소리 ×"]}},{"stem":"시우의 발표 자세 점검표예요. 가장 먼저 연습할 것은 무엇인가요?","options":[{"t":"듣는 친구들 바라보기","correct":true},{"t":"손 자연스럽게 내리기","mis":"K1-1-u2-X11"},{"t":"목소리 크기 맞추기","mis":"K1-1-u2-X12"}],"explanation":["점검표에서 ×는 눈 하나예요.","○인 것은 이미 잘하고 있어요.","안 된 것부터."],"asset":{"type":"passage","lines":["눈 × · 허리 ○ · 손 ○ · 다리 ○ · 목소리 ○"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L08_challenge#10','kor',1,1,'u2','L08','g1_1_kor_u2_L08_challenge','lesson_challenge','K1-1-u2-C6',4,'mc','auto','발표하는 친구와 앉아서 듣는 친구가 모두 지키면 좋은 자세는 어느 것인가요?',ARRAY['K1-1-u2-X13','K1-1-u2-X11']::text[],false,'{"seq":10,"concept":"K1-1-u2-C6","difficulty":4,"kind":"mc","stem":"발표하는 친구와 앉아서 듣는 친구가 모두 지키면 좋은 자세는 어느 것인가요?","options":[{"t":"허리를 곧게 세우기","correct":true},{"t":"다리를 어깨너비로 벌리고 서기","mis":"K1-1-u2-X13"},{"t":"손을 아래로 내리고 서 있기","mis":"K1-1-u2-X11"}],"explanation":["허리를 곧게 세우는 것은 말할 때도 들을 때도 같아요.","다리 벌리고 서기·손 내리고 서 있기는 서서 발표할 때의 자세예요.","듣는 사람은 앉아서 손을 무릎이나 책상 위에 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#1','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 눈은 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":1,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 눈은 어떻게 하나요?","options":[{"t":"말하는 사람을 바라봐요","correct":true},{"t":"창밖을 봐요","mis":"K1-1-u2-X13"},{"t":"책상 밑을 봐요","mis":"K1-1-u2-X13"}],"explanation":["말하는 사람을 보면 더 잘 들려요.","딴 곳을 보면 이야기를 놓치기 쉬워요.","듣기 자세 — 눈."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#2','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 귀는 어떻게 하나요?',ARRAY['K1-1-u2-X13','K1-1-u2-X14']::text[],false,'{"seq":2,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 귀는 어떻게 하나요?","options":[{"t":"귀를 기울여 들어요","correct":true},{"t":"다른 소리에 귀를 기울여요","mis":"K1-1-u2-X13"},{"t":"딴생각을 하며 들어요","mis":"K1-1-u2-X14"}],"explanation":["귀를 쫑긋 기울이면 내용을 놓치지 않아요.","딴 소리·딴생각은 이야기를 놓치게 해요.","듣기 자세 — 귀."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#3','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 허리는 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":3,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 허리는 어떻게 하나요?","options":[{"t":"등받이에 붙이고 곧게 세워 앉아요","correct":true},{"t":"책상에 엎드려요","mis":"K1-1-u2-X13"},{"t":"의자를 뒤로 젖혀요","mis":"K1-1-u2-X13"}],"explanation":["바르게 앉으면 오래 들어도 힘들지 않아요.","엎드리면 졸리고 이야기를 놓쳐요.","듣기 자세 — 허리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#4','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 손은 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":4,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 손은 어떻게 하나요?","options":[{"t":"무릎이나 책상 위에 가만히 놓아요","correct":true},{"t":"연필을 돌려요","mis":"K1-1-u2-X13"},{"t":"짝을 쿡쿡 찔러요","mis":"K1-1-u2-X13"}],"explanation":["손이 가만히 있어야 마음도 이야기에 가요.","손장난은 나도 친구도 방해해요.","듣기 자세 — 손."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#5','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',2,'ox','auto','이야기를 들을 때 다리를 흔들면 옆 친구도 집중하기 어려워요.',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":5,"concept":"K1-1-u2-C7","difficulty":2,"kind":"ox","stem":"이야기를 들을 때 다리를 흔들면 옆 친구도 집중하기 어려워요.","answer":"O","reason_options":[{"t":"흔들리는 다리에 눈이 가니까","correct":true},{"t":"다리는 흔들어야 졸리지 않으니까","mis":"K1-1-u2-X13"}],"mis":"K1-1-u2-X13","explanation":["다리는 가지런히 모아요.","흔들면 나도 옆 친구도 집중이 흐트러져요.","듣기 자세 — 다리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#6','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 도토리를 나누어 준 동물은 누구인가요?',ARRAY['K1-1-u2-X14']::text[],true,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 도토리를 나누어 준 동물은 누구인가요?","options":[{"t":"다람쥐","correct":true},{"t":"곰","mis":"K1-1-u2-X14"},{"t":"토끼","mis":"K1-1-u2-X14"}],"explanation":["다람쥐가 곰에게 도토리를 나누어 주었어요.","곰은 도토리를 받은 동물, 토끼는 나오지 않았어요.","「누가」를 기억하며 들어요."],"asset":{"type":"passage","lines":["다람쥐가 숲에서 도토리를 많이 주웠어요.","다람쥐는 배고픈 곰에게 도토리를 나누어 주었어요."],"title":"들은 이야기"},"variant_rule":{"alt":[{"stem":"이야기를 듣고 답해요. 반짝이는 돌을 찾은 동물은 누구인가요?","options":[{"t":"오리","correct":true},{"t":"거북","mis":"K1-1-u2-X14"},{"t":"개구리","mis":"K1-1-u2-X14"}],"explanation":["오리가 연못에서 돌을 찾았어요.","거북은 선물을 받았고, 개구리는 나오지 않았어요.","「누가」를 기억하며 들어요."],"asset":{"type":"passage","lines":["오리가 연못에서 반짝이는 돌을 찾았어요.","오리는 그 돌을 거북에게 선물했어요."],"title":"들은 이야기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#7','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 고슴도치는 무엇을 우산처럼 썼나요?',ARRAY['K1-1-u2-X14']::text[],true,'{"seq":7,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 고슴도치는 무엇을 우산처럼 썼나요?","options":[{"t":"커다란 잎","correct":true},{"t":"작은 꽃","mis":"K1-1-u2-X14"},{"t":"도토리 껍질","mis":"K1-1-u2-X14"}],"explanation":["고슴도치는 커다란 잎을 우산처럼 썼어요.","꽃·도토리 껍질은 이야기에 나오지 않아요.","「무엇을」을 기억하며 들어요."],"asset":{"type":"passage","lines":["비 오는 날, 고슴도치가 커다란 잎을 우산처럼 썼어요.","고슴도치는 비를 맞는 개구리와 함께 잎 아래에 섰어요."],"title":"들은 이야기"},"variant_rule":{"alt":[{"stem":"이야기를 듣고 답해요. 다람쥐는 곰에게 무엇을 나누어 주었나요?","options":[{"t":"도토리","correct":true},{"t":"밤","mis":"K1-1-u2-X14"},{"t":"사과","mis":"K1-1-u2-X14"}],"explanation":["다람쥐는 도토리를 나누어 주었어요.","밤·사과는 이야기에 나오지 않아요.","「무엇을」을 기억하며 들어요."],"asset":{"type":"passage","lines":["다람쥐가 숲에서 도토리를 많이 주웠어요.","다람쥐는 배고픈 곰에게 도토리를 나누어 주었어요."],"title":"들은 이야기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#8','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',2,'match','auto','몸의 부분과 들을 때의 바른 모습을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u2-C7","difficulty":2,"kind":"match","stem":"몸의 부분과 들을 때의 바른 모습을 이으세요.","pairs":[{"l":"눈","r":"말하는 사람 바라보기"},{"l":"귀","r":"기울여 듣기"},{"l":"다리","r":"가지런히 모으기"}],"mis":"K1-1-u2-X13","explanation":["눈-바라보기, 귀-기울이기, 다리-모으기.","다섯 가지 가운데 셋이에요.","허리·손도 잊지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸의 부분과 들을 때의 바른 모습을 이으세요.","pairs":[{"l":"허리","r":"곧게 세워 앉기"},{"l":"손","r":"무릎이나 책상 위에 놓기"},{"l":"눈","r":"말하는 사람 바라보기"}],"explanation":["허리-곧게, 손-가만히, 눈-바라보기.","다섯 가지 가운데 셋이에요.","귀·다리도 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#9','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',2,'error','auto','로아의 듣는 모습이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_basic#10','kor',1,1,'u2','L10','g1_1_kor_u2_L10_basic','lesson_basic','K1-1-u2-C7',3,'mc','auto','이야기를 중간에 놓치지 않으려면 듣기 전에 어떤 약속을 하면 좋을까요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":10,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"이야기를 중간에 놓치지 않으려면 듣기 전에 어떤 약속을 하면 좋을까요?","options":[{"t":"끝까지 듣기","correct":true},{"t":"궁금한 것이 생기면 바로 말하기","mis":"K1-1-u2-X14"},{"t":"재미있는 부분만 골라 듣기","mis":"K1-1-u2-X14"}],"explanation":["「끝까지」를 미리 약속하면 중간에 흐트러지지 않아요.","끼어들거나 골라 들으면 내용을 놓쳐요.","궁금한 것은 이야기가 끝난 뒤에 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#1','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 하늘이는 누구와 함께 감자를 캤나요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":1,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 하늘이는 누구와 함께 감자를 캤나요?","options":[{"t":"할머니","correct":true},{"t":"엄마","mis":"K1-1-u2-X14"},{"t":"동생","mis":"K1-1-u2-X14"}],"explanation":["하늘이는 할머니와 함께 감자를 캤어요.","엄마·동생은 이야기에 나오지 않아요.","「누구와」를 기억하며 들어요."],"asset":{"type":"passage","lines":["토요일에 하늘이는 할머니 댁에 갔어요.","하늘이는 할머니와 함께 텃밭에서 감자를 캤어요.","저녁에는 감자를 쪄서 맛있게 먹었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#2','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',2,'ox','auto','친구가 말할 때 궁금한 것이 생기면 바로 끼어들어 물어요.',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":2,"concept":"K1-1-u2-C7","difficulty":2,"kind":"ox","stem":"친구가 말할 때 궁금한 것이 생기면 바로 끼어들어 물어요.","answer":"X","reason_options":[{"t":"말이 끝난 뒤에 물어야 이야기를 끝까지 들을 수 있으니까","correct":true},{"t":"궁금한 건 잊기 전에 바로 말해야 하니까","mis":"K1-1-u2-X14"}],"mis":"K1-1-u2-X14","explanation":["끼어들면 말하는 친구도 나도 이야기를 놓쳐요.","궁금한 것은 기억해 두었다가 끝난 뒤 물어요.","끝까지 듣기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#3','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',3,'mc','auto','이야기를 듣고 답해요. 하늘이가 감자를 캔 곳은 어디인가요?',ARRAY['K1-1-u2-X14']::text[],true,'{"seq":3,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"이야기를 듣고 답해요. 하늘이가 감자를 캔 곳은 어디인가요?","options":[{"t":"할머니 댁 텃밭","correct":true},{"t":"학교 운동장","mis":"K1-1-u2-X14"},{"t":"집 앞 놀이터","mis":"K1-1-u2-X14"}],"explanation":["하늘이는 할머니 댁 텃밭에서 감자를 캤어요.","운동장·놀이터는 이야기에 나오지 않아요.","「어디서」를 기억하며 들어요."],"asset":{"type":"passage","lines":["토요일에 하늘이는 할머니 댁에 갔어요.","하늘이는 할머니와 함께 텃밭에서 감자를 캤어요.","저녁에는 감자를 쪄서 맛있게 먹었어요."],"title":"들은 이야기"},"variant_rule":{"alt":[{"stem":"이야기를 듣고 답해요. 생쥐가 아침에 간 곳은 어디인가요?","options":[{"t":"빵집","correct":true},{"t":"꽃집","mis":"K1-1-u2-X14"},{"t":"토끼네 집","mis":"K1-1-u2-X14"}],"explanation":["생쥐는 아침에 빵집에 갔어요.","토끼에게는 나중에 빵을 주었어요.","「어디서」를 기억하며 들어요."],"asset":{"type":"passage","lines":["아침에 생쥐가 빵집에 갔어요.","생쥐는 빵을 두 개 샀어요.","하나는 자기가 먹고, 하나는 아픈 토끼에게 주었어요."],"title":"들은 이야기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#4','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',3,'mc','auto','이야기를 듣고 답해요. 생쥐는 빵 하나를 누구에게 주었나요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":4,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"이야기를 듣고 답해요. 생쥐는 빵 하나를 누구에게 주었나요?","options":[{"t":"아픈 토끼","correct":true},{"t":"배고픈 곰","mis":"K1-1-u2-X14"},{"t":"빵집 주인","mis":"K1-1-u2-X14"}],"explanation":["생쥐는 빵 하나를 아픈 토끼에게 주었어요.","곰은 다른 이야기의 동물이고, 빵집 주인에게는 빵을 샀어요.","「누구에게」를 기억하며 들어요."],"asset":{"type":"passage","lines":["아침에 생쥐가 빵집에 갔어요.","생쥐는 빵을 두 개 샀어요.","하나는 자기가 먹고, 하나는 아픈 토끼에게 주었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#5','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',3,'error','auto','시우가 들은 이야기를 「곰이 다람쥐에게 도토리를 나누어 주었어요.」라고 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":5,"concept":"K1-1-u2-C7","difficulty":3,"kind":"error","stem":"시우가 들은 이야기를 「곰이 다람쥐에게 도토리를 나누어 주었어요.」라고 말했어요. 무엇이 잘못되었나요?","options":[{"t":"나누어 준 동물과 받은 동물을 바꾸어 말했어요","correct":true,"mis_target":"K1-1-u2-X14"},{"t":"도토리를 밤으로 바꾸어 말했어요","mis":"K1-1-u2-X14"},{"t":"이야기에 없는 토끼를 넣었어요","mis":"K1-1-u2-X14"}],"explanation":["다람쥐가 곰에게 나누어 주었어요.","도토리는 바르게 말했고 토끼는 말하지 않았어요.","「누가」와 「누구에게」를 함께 기억해요."],"asset":{"type":"passage","lines":["다람쥐가 숲에서 도토리를 많이 주웠어요.","다람쥐는 배고픈 곰에게 도토리를 나누어 주었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#6','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',3,'mc','auto','다섯 가지 듣기 자세를 모두 잘 지킨 친구는 누구인가요?',ARRAY['K1-1-u2-X13']::text[],true,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"다섯 가지 듣기 자세를 모두 잘 지킨 친구는 누구인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"K1-1-u2-X13"},{"t":"다","mis":"K1-1-u2-X13"}],"explanation":["「가」는 눈·귀·허리·손·다리를 모두 지켰어요.","「나」는 엎드렸고, 「다」는 연필을 돌렸어요.","다섯 가지를 하나씩 짚어요."],"asset":{"type":"passage","lines":["가: 말하는 친구를 보며 바르게 앉아 끝까지 들었어요.","나: 귀는 기울였지만 책상에 엎드려 있었어요.","다: 바르게 앉았지만 손으로 연필을 계속 돌렸어요."]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다섯 가지 듣기 자세를 모두 잘 지킨 친구는 누구인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"K1-1-u2-X13"},{"t":"다","mis":"K1-1-u2-X13"}],"explanation":["「나」는 다섯 가지를 모두 지켰어요.","「가」는 창밖을 보고, 「다」는 다리를 흔들었어요.","다섯 가지를 짚어요."],"asset":{"type":"passage","lines":["가: 바르게 앉았지만 창밖을 보며 들었어요.","나: 말하는 친구를 보며 손을 무릎에 두고 들었어요.","다: 귀를 기울였지만 다리를 계속 흔들었어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#7','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',3,'mc','auto','이야기를 집중해 들으면 좋은 점이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u2-X14','K1-1-u2-X13']::text[],false,'{"seq":7,"concept":"K1-1-u2-C7","difficulty":3,"kind":"mc","stem":"이야기를 집중해 들으면 좋은 점이 아닌 것은 어느 것인가요?","options":[{"t":"내가 말할 차례가 빨리 와요","correct":true},{"t":"이야기 내용을 잘 알 수 있어요","mis":"K1-1-u2-X14"},{"t":"말하는 친구가 힘이 나요","mis":"K1-1-u2-X13"}],"explanation":["집중해 들어도 내 차례가 빨리 오지는 않아요.","내용을 잘 알게 되고, 말하는 친구도 힘이 나요.","듣기는 나와 친구 모두를 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#8','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',4,'essay','teacher','들은 이야기를 두 문장으로 다시 말해 보고, 들을 때 지킨 자세 하나를 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u2-C7","difficulty":4,"kind":"essay","stem":"들은 이야기를 두 문장으로 다시 말해 보고, 들을 때 지킨 자세 하나를 써 보세요.","answer_guide":{"answer":"예: 「생쥐가 빵을 두 개 샀어요. 하나는 아픈 토끼에게 주었어요.」 — 말하는 사람을 바라보았어요.","scoring_points":["누가·무엇을 바르게 넣어 두 문장으로 말했는가","이야기에 없는 내용을 넣지 않았는가","듣기 자세를 하나 바르게 썼는가"]},"explanation":["누가·무엇을 넣어 두 문장.","이야기에 없는 내용은 빼요.","듣기 자세 하나."],"asset":{"type":"passage","lines":["아침에 생쥐가 빵집에 갔어요.","생쥐는 빵을 두 개 샀어요.","하나는 자기가 먹고, 하나는 아픈 토끼에게 주었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#9','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',4,'mc','auto','이야기를 듣고 답해요. 고슴도치가 개구리와 함께 잎 아래에 선 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K1-1-u2-X14']::text[],true,'{"seq":9,"concept":"K1-1-u2-C7","difficulty":4,"kind":"mc","stem":"이야기를 듣고 답해요. 고슴도치가 개구리와 함께 잎 아래에 선 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"개구리가 비를 맞고 있어서","correct":true},{"t":"개구리가 잎을 빌려 달라고 해서","mis":"K1-1-u2-X14"},{"t":"해가 너무 뜨거워서","mis":"K1-1-u2-X14"}],"explanation":["비를 맞는 개구리와 함께 잎 아래에 섰어요.","빌려 달라는 말·뜨거운 해는 이야기에 없어요.","들은 내용에서 까닭을 찾아요."],"asset":{"type":"passage","lines":["비 오는 날, 고슴도치가 커다란 잎을 우산처럼 썼어요.","고슴도치는 비를 맞는 개구리와 함께 잎 아래에 섰어요."],"title":"들은 이야기"},"variant_rule":{"alt":[{"stem":"이야기를 듣고 답해요. 생쥐가 빵을 두 개 산 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"하나는 아픈 토끼에게 주려고","correct":true},{"t":"하나는 저녁에 먹으려고","mis":"K1-1-u2-X14"},{"t":"빵집 주인이 하나를 더 주어서","mis":"K1-1-u2-X14"}],"explanation":["생쥐는 하나는 먹고, 하나는 아픈 토끼에게 주었어요.","저녁·덤 이야기는 나오지 않아요.","들은 내용에서 까닭을 찾아요."],"asset":{"type":"passage","lines":["아침에 생쥐가 빵집에 갔어요.","생쥐는 빵을 두 개 샀어요.","하나는 자기가 먹고, 하나는 아픈 토끼에게 주었어요."],"title":"들은 이야기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L10_challenge#10','kor',1,1,'u2','L10','g1_1_kor_u2_L10_challenge','lesson_challenge','K1-1-u2-C7',4,'mc','auto','이야기에 나오지 않은 내용은 어느 것인가요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":10,"concept":"K1-1-u2-C7","difficulty":4,"kind":"mc","stem":"이야기에 나오지 않은 내용은 어느 것인가요?","options":[{"t":"저녁에 감자를 할머니께 드렸어요","correct":true},{"t":"할머니와 함께 감자를 캤어요","mis":"K1-1-u2-X14"},{"t":"감자를 쪄서 먹었어요","mis":"K1-1-u2-X14"}],"explanation":["감자를 드렸다는 말은 이야기에 없어요.","감자를 캔 일·쪄서 먹은 일은 나와요.","들은 말과 짐작한 말을 가려요."],"asset":{"type":"passage","lines":["토요일에 하늘이는 할머니 댁에 갔어요.","하늘이는 할머니와 함께 텃밭에서 감자를 캤어요.","저녁에는 감자를 쪄서 맛있게 먹었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#1','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C8',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":1,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"곰","at":0,"pic":"🐻"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X05"},{"t":"ㄱ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「곰」이에요.","「고」에 받침 ㅁ을 넣어야 「곰」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
