INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#6','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"기린","at":1,"pic":"🦒"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㄹ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「기린」이에요.","「리」에 받침 ㄴ을 넣어야 「린」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#7','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C4',2,'mc','auto','받침 ㅁ이 들어간 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],true,'{"seq":7,"concept":"K1-1-u2-C4","difficulty":2,"kind":"mc","stem":"받침 ㅁ이 들어간 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"곰 · 밤 · 섬","correct":true},{"t":"곰 · 밥 · 섬","mis":"K1-1-u2-X05"},{"t":"공 · 밤 · 섬","mis":"K1-1-u2-X05"}],"explanation":["곰·밤·섬은 모두 받침 ㅁ이에요.","「밥」은 ㅂ, 「공」은 ㅇ이에요.","입술을 다무는 받침 ㅁ."],"variant_rule":{"alt":[{"stem":"받침 ㄹ이 들어간 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"달 · 별 · 물","correct":true},{"t":"달 · 별 · 문","mis":"K1-1-u2-X05"},{"t":"단 · 별 · 물","mis":"K1-1-u2-X05"}],"explanation":["달·별·물은 모두 받침 ㄹ이에요.","「문」·「단」은 ㄴ이에요.","ㄹ과 ㄴ을 견줘요."]},{"stem":"받침 ㅇ이 들어간 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"빵 · 콩 · 강","correct":true},{"t":"빵 · 콘 · 강","mis":"K1-1-u2-X05"},{"t":"빵 · 콩 · 감","mis":"K1-1-u2-X05"}],"explanation":["빵·콩·강은 모두 받침 ㅇ이에요.","「콘」은 ㄴ, 「감」은 ㅁ이에요.","코에서 울리는 받침 ㅇ."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#8','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":8,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"수박","at":1,"pic":"🍉"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「수박」이에요.","「바」에 받침 ㄱ을 넣어야 「박」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#9','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C8',2,'ox','auto','그림의 낱말을 「곱」이라고 써도 돼요.',ARRAY['K1-1-u2-X10']::text[],true,'{"seq":9,"concept":"K1-1-u2-C8","difficulty":2,"kind":"ox","stem":"그림의 낱말을 「곱」이라고 써도 돼요.","answer":"X","reason_options":[{"t":"그림은 곰이니까 받침 ㅁ을 넣어 「곰」이라고 써야 하니까","correct":true},{"t":"받침은 소리가 비슷하면 아무거나 넣어도 되니까","mis":"K1-1-u2-X10"}],"mis":"K1-1-u2-X10","explanation":["그림은 「곰」 — 받침 ㅁ.","「곱」은 그림과 다른 말이에요.","그림의 뜻에 맞는 받침을 넣어요."],"asset":{"type":"bat_word","w":"곰","at":0,"pic":"🐻"},"variant_rule":{"alt":[{"stem":"그림의 낱말을 「산」이라고 써요.","answer":"O","reason_options":[{"t":"그림은 산이니까 받침 ㄴ을 넣어야 하니까","correct":true},{"t":"받침은 아무거나 넣어도 같은 말이 되니까","mis":"K1-1-u2-X10"}],"explanation":["그림은 「산」 — 받침 ㄴ.","「상」·「삼」은 그림과 다른 말이에요.","뜻에 맞는 받침."],"asset":{"type":"bat_word","w":"산","at":0,"pic":"⛰️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_basic#10','kor',1,1,'u2','L12','g1_1_kor_u2_L12_basic','lesson_basic','K1-1-u2-C8',3,'error','auto','하린이가 그림을 보고 「사탄」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10','K1-1-u2-X03']::text[],true,'{"seq":10,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"하린이가 그림을 보고 「사탄」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「탕」의 받침을 ㅇ 대신 ㄴ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"「사」에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자 ㅌ을 ㄷ으로 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「사탕」 — 「탕」의 받침은 ㅇ.","ㄴ과 ㅇ은 소리가 비슷해 헷갈려요.","「사」와 ㅌ은 바르게 썼어요."],"asset":{"type":"bat_word","w":"사탕","at":1,"pic":"🍬"},"variant_rule":{"alt":[{"stem":"준우가 그림을 보고 「우상」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「산」의 받침을 ㄴ 대신 ㅇ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"「우」에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자 ㅅ을 ㅈ으로 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「우산」 — 「산」의 받침은 ㄴ.","ㄴ과 ㅇ은 소리가 비슷해 헷갈려요.","「우」와 ㅅ은 바르게 썼어요."],"asset":{"type":"bat_word","w":"우산","at":1,"pic":"☂️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
