INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#3','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',3,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"가방","at":1,"pic":"🎒"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「가방」이에요.","「바」에 받침 ㅇ을 넣어야 「방」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":3,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#4','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',3,'mc','auto','그림 낱말의 두 곳에 받침이 빠졌어요. 들어갈 받침을 차례대로 고르면 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],true,'{"seq":4,"concept":"K1-1-u2-C8","difficulty":3,"kind":"mc","stem":"그림 낱말의 두 곳에 받침이 빠졌어요. 들어갈 받침을 차례대로 고르면 어느 것인가요?","options":[{"t":"ㅇ, ㄴ","correct":true},{"t":"ㄴ, ㅇ","mis":"K1-1-u2-X05"},{"t":"ㅇ, ㅇ","mis":"K1-1-u2-X10"}],"explanation":["「푸 + ㅇ = 풍」, 「서 + ㄴ = 선」 — 풍선.","차례를 바꾸면 「푼성」, 둘 다 ㅇ이면 「풍성」이 돼요.","글자마다 받침을 따로 생각해요."],"asset":{"type":"scene","icon":"🎈","text":"푸□ 서□"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림 낱말의 두 곳에 받침이 빠졌어요. 들어갈 받침을 차례대로 고르면 어느 것인가요?","options":[{"t":"ㅇ, ㅂ","correct":true},{"t":"ㅂ, ㅇ","mis":"K1-1-u2-X05"},{"t":"ㄴ, ㅂ","mis":"K1-1-u2-X05"}],"explanation":["「자 + ㅇ = 장」, 「가 + ㅂ = 갑」 — 장갑.","차례를 바꾸거나 ㄴ을 넣으면 다른 말이 돼요.","글자마다 따로."],"asset":{"type":"scene","icon":"🧤","text":"자□ 가□"}},{"stem":"이번에는 다른 보기예요. 그림 낱말의 두 곳에 받침이 빠졌어요. 들어갈 받침을 차례대로 고르면 어느 것인가요?","options":[{"t":"ㄴ, ㄹ","correct":true},{"t":"ㄹ, ㄴ","mis":"K1-1-u2-X05"},{"t":"ㅇ, ㄹ","mis":"K1-1-u2-X05"}],"explanation":["「여 + ㄴ = 연」, 「피 + ㄹ = 필」 — 연필.","차례를 바꾸거나 ㅇ을 넣으면 다른 말이 돼요.","글자마다 따로."],"asset":{"type":"scene","icon":"✏️","text":"여□ 피□"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#5','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',3,'error','auto','민호가 그림을 보고 「호라이」라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X10','K1-1-u2-X03']::text[],true,'{"seq":5,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"민호가 그림을 보고 「호라이」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「랑」의 받침 ㅇ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「호」에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"「이」의 ㅇ을 받침으로 옮겨야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「호랑이」 — 「랑」에 받침 ㅇ.","받침을 빼면 다른 말처럼 들려요.","「호」·「이」는 받침이 없어요."],"asset":{"type":"bat_word","w":"호랑이","at":1,"pic":"🐯"},"variant_rule":{"alt":[{"stem":"다은이가 그림을 보고 「사스」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「슴」의 받침 ㅁ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「사」에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"「스」의 ㅅ을 받침으로 옮겨야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「사슴」 — 「슴」에 받침 ㅁ.","받침을 빼면 다른 말이 돼요.","「사」는 받침이 없어요."],"asset":{"type":"bat_word","w":"사슴","at":1,"pic":"🦌"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#6','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',3,'mc','auto','「곰」에서 받침만 하나 바꾸어 축구할 때 차는 「공」으로 만들려면 어떻게 하나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X10']::text[],true,'{"seq":6,"concept":"K1-1-u2-C8","difficulty":3,"kind":"mc","stem":"「곰」에서 받침만 하나 바꾸어 축구할 때 차는 「공」으로 만들려면 어떻게 하나요?","options":[{"t":"받침 ㅁ을 ㅇ으로 바꿔요","correct":true},{"t":"첫 자음자 ㄱ을 ㅇ으로 바꿔요","mis":"K1-1-u2-X09"},{"t":"받침 ㅁ을 ㄴ으로 바꿔요","mis":"K1-1-u2-X10"}],"explanation":["곰 → 공: 받침 ㅁ 자리에 ㅇ.","첫 자음자를 바꾸면 「옴」, ㄴ을 넣으면 「곤」이 돼요.","바꿀 곳은 맨 아래 받침 칸."],"asset":{"type":"bat","s":"곰","eq":false},"variant_rule":{"alt":[{"stem":"「달」에서 받침만 하나 바꾸어 집 둘레를 막는 「담」으로 만들려면 어떻게 하나요?","options":[{"t":"받침 ㄹ을 ㅁ으로 바꿔요","correct":true},{"t":"첫 자음자 ㄷ을 ㅁ으로 바꿔요","mis":"K1-1-u2-X09"},{"t":"받침 ㄹ을 ㄴ으로 바꿔요","mis":"K1-1-u2-X10"}],"explanation":["달 → 담: 받침 ㄹ 자리에 ㅁ.","첫 자음자를 바꾸면 「말」, ㄴ을 넣으면 「단」이 돼요.","바꿀 곳은 받침 칸."],"asset":{"type":"bat","s":"달","eq":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#7','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',3,'sa','auto','그림을 보고 받침 칸에 들어갈 자음자를 쓰세요.','{}'::text[],true,'{"seq":7,"kind":"sa","stem":"그림을 보고 받침 칸에 들어갈 자음자를 쓰세요.","asset":{"type":"bat_word","w":"밥","at":0,"pic":"🍚"},"answer":["ㅂ"],"explanation":["그림은 「밥」이에요.","「바」에 받침 ㅂ을 넣어야 「밥」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":3,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#8','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',4,'mc','auto','받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],true,'{"seq":8,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"연필","correct":true},{"t":"영필","mis":"K1-1-u2-X05"},{"t":"연피","mis":"K1-1-u2-X04"}],"explanation":["여 + ㄴ = 연, 피 + ㄹ = 필 — 연필.","「영필」은 받침 ㅇ을, 「연피」는 받침 하나를 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"✏️","text":"여□ 피□"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"장갑","correct":true},{"t":"잔갑","mis":"K1-1-u2-X05"},{"t":"장가","mis":"K1-1-u2-X04"}],"explanation":["자 + ㅇ = 장, 가 + ㅂ = 갑 — 장갑.","「잔갑」은 ㄴ을, 「장가」는 받침 ㅂ을 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"🧤","text":"자□ 가□"}},{"stem":"이번에는 다른 보기예요. 받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"풍선","correct":true},{"t":"푼선","mis":"K1-1-u2-X05"},{"t":"풍서","mis":"K1-1-u2-X04"}],"explanation":["푸 + ㅇ = 풍, 서 + ㄴ = 선 — 풍선.","「푼선」은 ㄴ을, 「풍서」는 받침 ㄴ을 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"🎈","text":"푸□ 서□"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#9','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',4,'essay','teacher','받침 ㅁ이 들어간 낱말과 받침 ㅇ이 들어간 낱말을 하나씩 쓰고, 그 낱말을 그림으로 어떻게 그릴지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u2-C8","difficulty":4,"kind":"essay","stem":"받침 ㅁ이 들어간 낱말과 받침 ㅇ이 들어간 낱말을 하나씩 쓰고, 그 낱말을 그림으로 어떻게 그릴지 말해 보세요.","answer_guide":{"answer":"예: 「곰」 — 동그란 귀가 있는 곰을 그려요. 「빵」 — 둥근 빵을 그려요.","scoring_points":["받침 ㅁ 낱말을 바르게 썼는가","받침 ㅇ 낱말을 바르게 썼는가","낱말과 그림이 서로 맞는가"]},"explanation":["받침 ㅁ 낱말 하나.","받침 ㅇ 낱말 하나.","그림과 낱말의 뜻이 같아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_L12_challenge#10','kor',1,1,'u2','L12','g1_1_kor_u2_L12_challenge','lesson_challenge','K1-1-u2-C8',4,'mc','auto','「바□」에 받침을 넣었어요. 그림과 낱말이 바르게 이어진 것은 어느 것인가요?',ARRAY['K1-1-u2-X10']::text[],true,'{"seq":10,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"「바□」에 받침을 넣었어요. 그림과 낱말이 바르게 이어진 것은 어느 것인가요?","options":[{"t":"🍚 — 밥","correct":true},{"t":"🍚 — 밤","mis":"K1-1-u2-X10"},{"t":"🍚 — 방","mis":"K1-1-u2-X10"}],"explanation":["🍚 그림은 「밥」 — 받침 ㅂ.","「밤」·「방」은 받침 하나 차이로 뜻이 달라요.","그림의 뜻에 맞는 받침."],"variant_rule":{"alt":[{"stem":"「다□」에 받침을 넣었어요. 그림과 낱말이 바르게 이어진 것은 어느 것인가요?","options":[{"t":"🌙 — 달","correct":true},{"t":"🌙 — 단","mis":"K1-1-u2-X10"},{"t":"🌙 — 담","mis":"K1-1-u2-X10"}],"explanation":["🌙 그림은 「달」 — 받침 ㄹ.","「단」·「담」은 받침 하나 차이로 뜻이 달라요.","그림의 뜻에 맞는 받침."]},{"stem":"「고□」에 받침을 넣었어요. 그림과 낱말이 바르게 이어진 것은 어느 것인가요?","options":[{"t":"⚽ — 공","correct":true},{"t":"⚽ — 곰","mis":"K1-1-u2-X10"},{"t":"⚽ — 곤","mis":"K1-1-u2-X10"}],"explanation":["⚽ 그림은 「공」 — 받침 ㅇ.","「곰」·「곤」은 받침이 달라요.","그림의 뜻에 맞는 받침."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#1','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C1',1,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"봄","correct":true},{"t":"보","mis":"K1-1-u2-X01"},{"t":"가","mis":"K1-1-u2-X01"}],"explanation":["「봄」은 아래쪽에 받침 ㅁ이 있어요.","「보」·「가」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#2','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C2',1,'mc','auto','「강」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「강」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"강","eq":false,"lay":"blank"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄱ","mis":"K1-1-u2-X03"},{"t":"ㄴ","mis":"K1-1-u2-X05"}],"explanation":["「강」은 ㄱ + ㅏ + 받침 ㅇ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄱ은 첫소리, 받침 ㅇ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#3','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C3',1,'mc','auto','「코」에 받침 ㅇ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":3,"kind":"mc","stem":"「코」에 받침 ㅇ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"코","b":"ㅇ","s":null,"lay":true},"options":[{"t":"콩","correct":true},{"t":"코","mis":"K1-1-u2-X04"},{"t":"콘","mis":"K1-1-u2-X05"}],"explanation":["「코」 아래쪽에 받침 ㅇ을 더하면 「콩」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「콩」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#4','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C4',1,'mc','auto','끝소리에서 입술을 꼭 다무는 받침 ㅁ이 들어간 글자는 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],false,'{"seq":4,"concept":"K1-1-u2-C4","difficulty":1,"kind":"mc","stem":"끝소리에서 입술을 꼭 다무는 받침 ㅁ이 들어간 글자는 어느 것인가요?","options":[{"t":"봄","correct":true},{"t":"봉","mis":"K1-1-u2-X05"},{"t":"본","mis":"K1-1-u2-X05"}],"explanation":["「봄」은 받침 ㅁ — 입술을 다물어요.","「봉」은 ㅇ, 「본」은 ㄴ이에요.","끝소리의 입 모양을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#5','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C6',1,'mc','auto','발표할 때 눈은 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 눈은 어떻게 하나요?","options":[{"t":"듣는 친구들을 바라봐요","correct":true},{"t":"바닥을 내려다봐요","mis":"K1-1-u2-X11"},{"t":"창밖을 봐요","mis":"K1-1-u2-X11"}],"explanation":["눈으로 친구들을 바라봐요.","딴 곳을 보면 마음이 전해지지 않아요.","발표 자세 — 눈."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#6','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 눈은 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 눈은 어떻게 하나요?","options":[{"t":"말하는 사람을 바라봐요","correct":true},{"t":"창밖을 봐요","mis":"K1-1-u2-X13"},{"t":"짝의 공책을 봐요","mis":"K1-1-u2-X13"}],"explanation":["말하는 사람을 바라봐요.","딴 곳을 보면 이야기를 놓쳐요.","듣기 자세 — 눈."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#7','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C8',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"곰","at":0,"pic":"🐻"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X05"},{"t":"ㄱ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「곰」이에요.","「고」에 받침 ㅁ을 넣어야 「곰」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#8','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C2',1,'mc','auto','받침은 글자의 어디에 들어가나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],false,'{"seq":8,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"받침은 글자의 어디에 들어가나요?","options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u2-X02"},{"t":"위쪽","mis":"K1-1-u2-X03"}],"explanation":["받침은 글자 맨 아래쪽에 들어가요.","오른쪽은 모음자, 위쪽은 첫 자음자 자리예요.","받침 자리는 하나 — 맨 아래."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#9','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C1',2,'mc','auto','받침이 없는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":9,"kind":"mc","stem":"받침이 없는 글자는 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"감","mis":"K1-1-u2-X01"},{"t":"문","mis":"K1-1-u2-X01"}],"explanation":["「가」는 아래쪽이 비어 있어요.","「감」·「문」은 아래쪽에 받침이 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":2,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"},"neg":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#10','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C3',2,'mc','auto','바 + 받침 ㅂ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X06']::text[],true,'{"seq":10,"kind":"mc","stem":"바 + 받침 ㅂ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"바","b":"ㅂ","s":null},"options":[{"t":"밥","correct":true},{"t":"바ㅂ","mis":"K1-1-u2-X02"},{"t":"법","mis":"K1-1-u2-X06"}],"explanation":["「바」 아래쪽에 받침 ㅂ을 더하면 「밥」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「밥」은 받침 ㅂ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#11','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C4',2,'mc','auto','「곧」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":11,"kind":"mc","stem":"「곧」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"곧","eq":false},"options":[{"t":"ㄷ","correct":true},{"t":"ㄱ","mis":"K1-1-u2-X03"},{"t":"ㅅ","mis":"K1-1-u2-X05"}],"explanation":["「곧」은 ㄱ + ㅗ + 받침 ㄷ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄱ은 첫소리, 받침 ㄷ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#12','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C5',2,'mc','auto','「반」의 받침 ㄴ을 ㅁ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":12,"kind":"mc","stem":"「반」의 받침 ㄴ을 ㅁ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"반","eq":false},"options":[{"t":"밤","correct":true},{"t":"만","mis":"K1-1-u2-X09"},{"t":"반","mis":"K1-1-u2-X08"}],"explanation":["「반」에서 받침 ㄴ 자리에 ㅁ을 넣으면 「밤」이에요.","맨 앞 자음자 ㅂ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#13','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C5',2,'ox','auto','「밤」과 「밥」은 받침만 다르니 뜻이 같아요.',ARRAY['K1-1-u2-X08']::text[],false,'{"seq":13,"concept":"K1-1-u2-C5","difficulty":2,"kind":"ox","stem":"「밤」과 「밥」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"mis":"K1-1-u2-X08","explanation":["「밤」은 깜깜한 때, 「밥」은 먹는 것.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#14','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":14,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"기린","at":1,"pic":"🦒"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㄹ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「기린」이에요.","「리」에 받침 ㄴ을 넣어야 「린」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#15','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C2',2,'mc','auto','「산」을 세 부분으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],false,'{"seq":15,"concept":"K1-1-u2-C2","difficulty":2,"kind":"mc","stem":"「산」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㅅ + ㅏ + 받침 ㄴ","correct":true},{"t":"ㅅ + ㄴ + 받침 ㅏ","mis":"K1-1-u2-X07"},{"t":"ㄴ + ㅏ + 받침 ㅅ","mis":"K1-1-u2-X03"}],"explanation":["「산」은 첫 자음자 ㅅ, 모음자 ㅏ, 받침 ㄴ이에요.","모음자는 받침이 될 수 없고, 첫 자음자와 받침은 자리가 달라요.","위쪽부터 차례로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#16','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 도토리를 나누어 준 동물은 누구인가요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":16,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 도토리를 나누어 준 동물은 누구인가요?","options":[{"t":"다람쥐","correct":true},{"t":"곰","mis":"K1-1-u2-X14"},{"t":"토끼","mis":"K1-1-u2-X14"}],"explanation":["다람쥐가 곰에게 나누어 주었어요.","곰은 받은 동물이에요.","「누가」를 기억해요."],"asset":{"type":"passage","lines":["다람쥐가 숲에서 도토리를 많이 주웠어요.","다람쥐는 배고픈 곰에게 도토리를 나누어 주었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#17','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C1',3,'error','auto','은솔이가 받침이 있는 글자만 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#18','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C3',3,'error','auto','준우가 「사」에 받침 ㄴ을 더해 「사ㄴ」처럼 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X05','K1-1-u2-X06']::text[],false,'{"seq":18,"concept":"K1-1-u2-C3","difficulty":3,"kind":"error","stem":"준우가 「사」에 받침 ㄴ을 더해 「사ㄴ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「산」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㄴ 대신 ㅇ을 더해야 해요 — 「상」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「선」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","사 + 받침 ㄴ = 산.","옆에 따로 쓰면 한 글자가 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#19','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C4',3,'error','auto','민호가 「낙타」를 「나타」라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05','K1-1-u2-X03']::text[],false,'{"seq":19,"concept":"K1-1-u2-C4","difficulty":3,"kind":"error","stem":"민호가 「낙타」를 「나타」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「낙」의 받침 ㄱ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「낙」의 받침을 ㅇ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「낙」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「낙」에는 받침 ㄱ이 있어요.","받침을 빼면 다른 말처럼 들려요.","받침 소리까지 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#20','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C5',3,'mc','auto','「바」에 받침을 붙여 「해가 지고 깜깜한 때」를 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],false,'{"seq":20,"concept":"K1-1-u2-C5","difficulty":3,"kind":"mc","stem":"「바」에 받침을 붙여 「해가 지고 깜깜한 때」를 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㅁ — 「밤」","correct":true},{"t":"받침 ㅂ — 「밥」","mis":"K1-1-u2-X05"},{"t":"받침 ㅇ — 「방」","mis":"K1-1-u2-X10"}],"explanation":["바 + 받침 ㅁ = 밤.","받침이 다르면 뜻이 달라요.","뜻을 생각해 받침을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#21','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C6',3,'mc','auto','서윤이는 발표할 때 친구들을 보고 허리를 폈어요. 그런데 목소리가 너무 작았어요. 서윤에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X11','K1-1-u2-X12']::text[],false,'{"seq":21,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"서윤이는 발표할 때 친구들을 보고 허리를 폈어요. 그런데 목소리가 너무 작았어요. 서윤에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"뒷자리 친구에게도 들리게 조금 더 크게 말해 봐","correct":true},{"t":"눈을 감고 말하면 덜 떨려","mis":"K1-1-u2-X11"},{"t":"빨리 말하고 얼른 들어가","mis":"K1-1-u2-X12"}],"explanation":["서윤이가 고칠 것은 하나예요.","잘한 것은 두고 고칠 점만 말해 줘요.","다섯 가지 자세 — 눈·허리·손·다리·목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#22','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C8',3,'error','auto','다은이가 그림을 보고 「사탄」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10','K1-1-u2-X03']::text[],false,'{"seq":22,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"다은이가 그림을 보고 「사탄」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「탕」의 받침을 ㅇ 대신 ㄴ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"다른 글자에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자를 바꿔 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「사탕」 — 받침 ㅇ.","소리가 비슷한 받침과 헷갈렸어요.","그림의 뜻에 맞는 받침을 넣어요."],"asset":{"type":"bat_word","w":"사탕","at":1,"pic":"🍬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#23','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C4',4,'mc','auto','다음 글에서 받침 ㄹ이 들어간 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X15']::text[],false,'{"seq":23,"concept":"K1-1-u2-C4","difficulty":4,"kind":"mc","stem":"다음 글에서 받침 ㄹ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u2-X15"},{"t":"6개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㄹ 글자: 달 · 별 · 을 · 불.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["달님이 별을 불렀어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#24','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C2',4,'essay','teacher','「차」와 「창」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-1-u2-C2","difficulty":4,"kind":"essay","stem":"「차」와 「창」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.","answer_guide":{"answer":"예: 「창」은 「차」의 아래쪽에 받침 ㅇ이 들어갔어요. 받침 소리까지 읽으면 끝소리가 달라져요.","scoring_points":["받침이 아래쪽에 들어갔다고 말했는가","받침 ㅇ을 바르게 찾았는가","소리가 달라졌다고 말했는가"]},"explanation":["받침 자리는 아래쪽.","받침은 ㅇ.","받침이 생기면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_a#25','kor',1,1,'u2','','g1_1_kor_u2_review_a','unit_review','K1-1-u2-C8',4,'mc','auto','받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],false,'{"seq":25,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"연필","correct":true},{"t":"영필","mis":"K1-1-u2-X05"},{"t":"연피","mis":"K1-1-u2-X04"}],"explanation":["여 + ㄴ = 연, 피 + ㄹ = 필.","「영필」은 비슷한 받침을, 「연피」는 받침 하나를 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"✏️","text":"여□ 피□"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#1','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C1',1,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"눈","correct":true},{"t":"누","mis":"K1-1-u2-X01"},{"t":"빠","mis":"K1-1-u2-X01"}],"explanation":["「눈」은 아래쪽에 받침 ㄴ이 있어요.","「누」·「빠」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#2','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C2',1,'mc','auto','「손」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「손」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"손","eq":false,"lay":"blank"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅅ","mis":"K1-1-u2-X03"},{"t":"ㅇ","mis":"K1-1-u2-X05"}],"explanation":["「손」은 ㅅ + ㅗ + 받침 ㄴ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅅ은 첫소리, 받침 ㄴ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#3','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C3',1,'mc','auto','「사」에 받침 ㄴ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":3,"kind":"mc","stem":"「사」에 받침 ㄴ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"사","b":"ㄴ","s":null,"lay":true},"options":[{"t":"산","correct":true},{"t":"사","mis":"K1-1-u2-X04"},{"t":"상","mis":"K1-1-u2-X05"}],"explanation":["「사」 아래쪽에 받침 ㄴ을 더하면 「산」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「산」은 받침 ㄴ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#4','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C4',1,'mc','auto','끝소리가 코에서 길게 울리는 받침 ㅇ이 들어간 글자는 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],false,'{"seq":4,"concept":"K1-1-u2-C4","difficulty":1,"kind":"mc","stem":"끝소리가 코에서 길게 울리는 받침 ㅇ이 들어간 글자는 어느 것인가요?","options":[{"t":"콩","correct":true},{"t":"콘","mis":"K1-1-u2-X05"},{"t":"콤","mis":"K1-1-u2-X05"}],"explanation":["「콩」은 받침 ㅇ — 코에서 울려요.","「콘」은 ㄴ, 「콤」은 ㅁ이에요.","끝소리를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#5','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C6',1,'mc','auto','발표할 때 허리는 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 허리는 어떻게 하나요?","options":[{"t":"곧게 세워요","correct":true},{"t":"삐딱하게 기대요","mis":"K1-1-u2-X11"},{"t":"앞으로 푹 숙여요","mis":"K1-1-u2-X11"}],"explanation":["허리를 곧게 세워요.","기대거나 숙이면 목소리가 잘 안 나와요.","발표 자세 — 허리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#6','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 허리는 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 허리는 어떻게 하나요?","options":[{"t":"곧게 세워 앉아요","correct":true},{"t":"책상에 엎드려요","mis":"K1-1-u2-X13"},{"t":"의자를 뒤로 젖혀요","mis":"K1-1-u2-X13"}],"explanation":["곧게 세워 앉아요.","엎드리면 졸리고 놓쳐요.","듣기 자세 — 허리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#7','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C8',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"집","at":0,"pic":"🏠"},"options":[{"t":"ㅂ","correct":true},{"t":"ㅁ","mis":"K1-1-u2-X05"},{"t":"ㅈ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「집」이에요.","「지」에 받침 ㅂ을 넣어야 「집」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#8','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C2',1,'mc','auto','「강」에서 받침 ㅇ은 어디에 있나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],false,'{"seq":8,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"「강」에서 받침 ㅇ은 어디에 있나요?","options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u2-X02"},{"t":"위쪽 왼쪽","mis":"K1-1-u2-X03"}],"explanation":["받침 ㅇ은 「강」의 아래쪽에 있어요.","오른쪽은 ㅏ, 위쪽 왼쪽은 ㄱ 자리예요.","받침은 아래쪽."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#9','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C1',2,'mc','auto','받침이 없는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":9,"kind":"mc","stem":"받침이 없는 글자는 어느 것인가요?","options":[{"t":"바","correct":true},{"t":"밤","mis":"K1-1-u2-X01"},{"t":"공","mis":"K1-1-u2-X01"}],"explanation":["「바」는 아래쪽이 비어 있어요.","「밤」·「공」은 아래쪽에 받침이 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":2,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"},"neg":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#10','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C3',2,'mc','auto','나 + 받침 ㄱ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X06']::text[],true,'{"seq":10,"kind":"mc","stem":"나 + 받침 ㄱ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"나","b":"ㄱ","s":null},"options":[{"t":"낙","correct":true},{"t":"나ㄱ","mis":"K1-1-u2-X02"},{"t":"넉","mis":"K1-1-u2-X06"}],"explanation":["「나」 아래쪽에 받침 ㄱ을 더하면 「낙」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「낙」은 받침 ㄱ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#11','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C4',2,'mc','auto','「책」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":11,"kind":"mc","stem":"「책」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"책","eq":false},"options":[{"t":"ㄱ","correct":true},{"t":"ㅊ","mis":"K1-1-u2-X03"},{"t":"ㅇ","mis":"K1-1-u2-X05"}],"explanation":["「책」은 ㅊ + ㅐ + 받침 ㄱ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅊ은 첫소리, 받침 ㄱ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#12','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C5',2,'mc','auto','「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":12,"kind":"mc","stem":"「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"곰","eq":false},"options":[{"t":"공","correct":true},{"t":"옴","mis":"K1-1-u2-X09"},{"t":"곰","mis":"K1-1-u2-X08"}],"explanation":["「곰」에서 받침 ㅁ 자리에 ㅇ을 넣으면 「공」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅗ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#13','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C5',2,'ox','auto','「달」과 「담」은 받침만 다르니 뜻이 같아요.',ARRAY['K1-1-u2-X08']::text[],false,'{"seq":13,"concept":"K1-1-u2-C5","difficulty":2,"kind":"ox","stem":"「달」과 「담」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"mis":"K1-1-u2-X08","explanation":["「달」은 하늘에 뜨는 것, 「담」은 집 둘레를 막는 것.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#14','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":14,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"수박","at":1,"pic":"🍉"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「수박」이에요.","「바」에 받침 ㄱ을 넣어야 「박」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#15','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C2',2,'mc','auto','「곰」을 세 부분으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],false,'{"seq":15,"concept":"K1-1-u2-C2","difficulty":2,"kind":"mc","stem":"「곰」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㄱ + ㅗ + 받침 ㅁ","correct":true},{"t":"ㄱ + ㅁ + 받침 ㅗ","mis":"K1-1-u2-X07"},{"t":"ㅁ + ㅗ + 받침 ㄱ","mis":"K1-1-u2-X03"}],"explanation":["「곰」은 첫 자음자 ㄱ, 모음자 ㅗ, 받침 ㅁ이에요.","모음자는 받침이 될 수 없고, 첫 자음자와 받침은 자리가 달라요.","위쪽부터 차례로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#16','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 오리가 돌을 선물한 동물은 누구인가요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":16,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 오리가 돌을 선물한 동물은 누구인가요?","options":[{"t":"거북","correct":true},{"t":"개구리","mis":"K1-1-u2-X14"},{"t":"오리","mis":"K1-1-u2-X14"}],"explanation":["오리는 돌을 거북에게 선물했어요.","개구리는 나오지 않고, 오리는 선물한 동물이에요.","「누구에게」를 기억해요."],"asset":{"type":"passage","lines":["오리가 연못에서 반짝이는 돌을 찾았어요.","오리는 그 돌을 거북에게 선물했어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#17','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C1',3,'error','auto','태민이가 받침이 있는 글자만 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#18','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C3',3,'error','auto','하린이가 「무」에 받침 ㄹ을 더해 「무ㄹ」처럼 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X05','K1-1-u2-X06']::text[],false,'{"seq":18,"concept":"K1-1-u2-C3","difficulty":3,"kind":"error","stem":"하린이가 「무」에 받침 ㄹ을 더해 「무ㄹ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「물」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㄹ 대신 ㄴ을 더해야 해요 — 「문」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「몰」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","무 + 받침 ㄹ = 물.","옆에 따로 쓰면 한 글자가 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#19','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C4',3,'error','auto','로아가 「연필」을 「여필」이라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05','K1-1-u2-X03']::text[],false,'{"seq":19,"concept":"K1-1-u2-C4","difficulty":3,"kind":"error","stem":"로아가 「연필」을 「여필」이라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「연」의 받침 ㄴ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「연」의 받침을 ㅇ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「연」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「연」에는 받침 ㄴ이 있어요.","받침을 빼면 다른 말처럼 들려요.","받침 소리까지 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#20','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C5',3,'mc','auto','「바」에 받침을 붙여 「걸을 때 쓰는 몸의 한 부분」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],false,'{"seq":20,"concept":"K1-1-u2-C5","difficulty":3,"kind":"mc","stem":"「바」에 받침을 붙여 「걸을 때 쓰는 몸의 한 부분」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㄹ — 「발」","correct":true},{"t":"받침 ㄴ — 「반」","mis":"K1-1-u2-X05"},{"t":"받침 ㄱ — 「박」","mis":"K1-1-u2-X10"}],"explanation":["바 + 받침 ㄹ = 발.","받침이 다르면 뜻이 달라요.","뜻을 생각해 받침을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#21','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C6',3,'mc','auto','준우는 발표할 때 또박또박 말하고 허리를 폈어요. 그런데 계속 바닥만 내려다봤어요. 준우에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X12','K1-1-u2-X11']::text[],false,'{"seq":21,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"준우는 발표할 때 또박또박 말하고 허리를 폈어요. 그런데 계속 바닥만 내려다봤어요. 준우에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 친구들을 바라보며 말해 봐","correct":true},{"t":"목소리를 더 작게 해 봐","mis":"K1-1-u2-X12"},{"t":"손을 주머니에 넣어 봐","mis":"K1-1-u2-X11"}],"explanation":["준우가 고칠 것은 하나예요.","잘한 것은 두고 고칠 점만 말해 줘요.","다섯 가지 자세 — 눈·허리·손·다리·목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#22','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C8',3,'error','auto','은솔이가 그림을 보고 「우상」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10','K1-1-u2-X03']::text[],false,'{"seq":22,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"은솔이가 그림을 보고 「우상」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「산」의 받침을 ㄴ 대신 ㅇ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"다른 글자에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자를 바꿔 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「우산」 — 받침 ㄴ.","소리가 비슷한 받침과 헷갈렸어요.","그림의 뜻에 맞는 받침을 넣어요."],"asset":{"type":"bat_word","w":"우산","at":1,"pic":"☂️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#23','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C4',4,'mc','auto','다음 글에서 받침 ㅁ이 들어간 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X15']::text[],false,'{"seq":23,"concept":"K1-1-u2-C4","difficulty":4,"kind":"mc","stem":"다음 글에서 받침 ㅁ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-1-u2-X15"},{"t":"4개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㅁ 글자: 엄 · 감.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["엄마랑 감을 따러 산에 갔어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#24','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C2',4,'essay','teacher','「사」와 「산」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-1-u2-C2","difficulty":4,"kind":"essay","stem":"「사」와 「산」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.","answer_guide":{"answer":"예: 「산」은 「사」의 아래쪽에 받침 ㄴ이 들어갔어요. 받침 소리까지 읽으면 끝소리가 달라져요.","scoring_points":["받침이 아래쪽에 들어갔다고 말했는가","받침 ㄴ을 바르게 찾았는가","소리가 달라졌다고 말했는가"]},"explanation":["받침 자리는 아래쪽.","받침은 ㄴ.","받침이 생기면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_b#25','kor',1,1,'u2','','g1_1_kor_u2_review_b','unit_review','K1-1-u2-C8',4,'mc','auto','받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],false,'{"seq":25,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"장갑","correct":true},{"t":"잔갑","mis":"K1-1-u2-X05"},{"t":"장가","mis":"K1-1-u2-X04"}],"explanation":["자 + ㅇ = 장, 가 + ㅂ = 갑.","「잔갑」은 비슷한 받침을, 「장가」는 받침 하나를 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"🧤","text":"자□ 가□"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#1','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C1',1,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"달","correct":true},{"t":"다","mis":"K1-1-u2-X01"},{"t":"고","mis":"K1-1-u2-X01"}],"explanation":["「달」은 아래쪽에 받침 ㄹ이 있어요.","「다」·「고」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#2','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C2',1,'mc','auto','「물」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「물」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"물","eq":false,"lay":"blank"},"options":[{"t":"ㄹ","correct":true},{"t":"ㅁ","mis":"K1-1-u2-X03"},{"t":"ㄴ","mis":"K1-1-u2-X05"}],"explanation":["「물」은 ㅁ + ㅜ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅁ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#3','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C3',1,'mc','auto','「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":3,"kind":"mc","stem":"「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"고","b":"ㅁ","s":null,"lay":true},"options":[{"t":"곰","correct":true},{"t":"고","mis":"K1-1-u2-X04"},{"t":"곱","mis":"K1-1-u2-X05"}],"explanation":["「고」 아래쪽에 받침 ㅁ을 더하면 「곰」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「곰」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#4','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C4',1,'mc','auto','혀가 입천장에 살짝 닿는 받침 ㄹ이 들어간 글자는 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],false,'{"seq":4,"concept":"K1-1-u2-C4","difficulty":1,"kind":"mc","stem":"혀가 입천장에 살짝 닿는 받침 ㄹ이 들어간 글자는 어느 것인가요?","options":[{"t":"별","correct":true},{"t":"변","mis":"K1-1-u2-X05"},{"t":"병","mis":"K1-1-u2-X05"}],"explanation":["「별」은 받침 ㄹ이에요.","「변」은 ㄴ, 「병」은 ㅇ이에요.","끝소리를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#5','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C6',1,'mc','auto','발표할 때 목소리는 어떻게 하나요?',ARRAY['K1-1-u2-X12']::text[],false,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 목소리는 어떻게 하나요?","options":[{"t":"알맞은 크기로 또박또박 말해요","correct":true},{"t":"작게 우물우물 말해요","mis":"K1-1-u2-X12"},{"t":"아주 크게 소리쳐요","mis":"K1-1-u2-X12"}],"explanation":["또박또박 알맞게 말해요.","너무 작거나 크면 듣기 힘들어요.","발표 자세 — 목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#6','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 손은 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 손은 어떻게 하나요?","options":[{"t":"무릎이나 책상 위에 가만히 놓아요","correct":true},{"t":"지우개를 굴려요","mis":"K1-1-u2-X13"},{"t":"짝을 쿡쿡 찔러요","mis":"K1-1-u2-X13"}],"explanation":["손은 가만히.","손장난은 나도 친구도 방해해요.","듣기 자세 — 손."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#7','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C8',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"별","at":0,"pic":"⭐"},"options":[{"t":"ㄹ","correct":true},{"t":"ㄴ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「별」이에요.","「벼」에 받침 ㄹ을 넣어야 「별」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#8','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C2',1,'mc','auto','「곰」에서 받침 ㅁ은 어디에 있나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],false,'{"seq":8,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"「곰」에서 받침 ㅁ은 어디에 있나요?","options":[{"t":"맨 아래쪽","correct":true},{"t":"ㅗ 오른쪽","mis":"K1-1-u2-X02"},{"t":"맨 위쪽","mis":"K1-1-u2-X03"}],"explanation":["받침 ㅁ은 「곰」의 맨 아래쪽에 있어요.","맨 위쪽은 첫 자음자 ㄱ 자리예요.","받침은 맨 아래쪽."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#9','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C1',2,'mc','auto','받침이 없는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":9,"kind":"mc","stem":"받침이 없는 글자는 어느 것인가요?","options":[{"t":"사","correct":true},{"t":"산","mis":"K1-1-u2-X01"},{"t":"목","mis":"K1-1-u2-X01"}],"explanation":["「사」는 아래쪽이 비어 있어요.","「산」·「목」은 아래쪽에 받침이 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":2,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"},"neg":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#10','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C3',2,'mc','auto','가 + 받침 ㅁ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X06']::text[],true,'{"seq":10,"kind":"mc","stem":"가 + 받침 ㅁ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"가","b":"ㅁ","s":null},"options":[{"t":"감","correct":true},{"t":"가ㅁ","mis":"K1-1-u2-X02"},{"t":"검","mis":"K1-1-u2-X06"}],"explanation":["「가」 아래쪽에 받침 ㅁ을 더하면 「감」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「감」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#11','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C4',2,'mc','auto','「발」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":11,"kind":"mc","stem":"「발」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"발","eq":false},"options":[{"t":"ㄹ","correct":true},{"t":"ㅂ","mis":"K1-1-u2-X03"},{"t":"ㄴ","mis":"K1-1-u2-X05"}],"explanation":["「발」은 ㅂ + ㅏ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#12','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C5',2,'mc','auto','「물」의 받침 ㄹ을 ㄴ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":12,"kind":"mc","stem":"「물」의 받침 ㄹ을 ㄴ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"물","eq":false},"options":[{"t":"문","correct":true},{"t":"눌","mis":"K1-1-u2-X09"},{"t":"물","mis":"K1-1-u2-X08"}],"explanation":["「물」에서 받침 ㄹ 자리에 ㄴ을 넣으면 「문」이에요.","맨 앞 자음자 ㅁ과 모음자 ㅜ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#13','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C5',2,'ox','auto','「공」과 「곰」은 받침만 다르니 뜻이 같아요.',ARRAY['K1-1-u2-X08']::text[],false,'{"seq":13,"concept":"K1-1-u2-C5","difficulty":2,"kind":"ox","stem":"「공」과 「곰」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"mis":"K1-1-u2-X08","explanation":["「공」은 차는 것, 「곰」은 숲에 사는 동물.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#14','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":14,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"거북","at":1,"pic":"🐢"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「거북」이에요.","「부」에 받침 ㄱ을 넣어야 「북」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#15','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C2',2,'mc','auto','「물」을 세 부분으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],false,'{"seq":15,"concept":"K1-1-u2-C2","difficulty":2,"kind":"mc","stem":"「물」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㅁ + ㅜ + 받침 ㄹ","correct":true},{"t":"ㅁ + ㄹ + 받침 ㅜ","mis":"K1-1-u2-X07"},{"t":"ㄹ + ㅜ + 받침 ㅁ","mis":"K1-1-u2-X03"}],"explanation":["「물」은 첫 자음자 ㅁ, 모음자 ㅜ, 받침 ㄹ이에요.","모음자는 받침이 될 수 없고, 첫 자음자와 받침은 자리가 달라요.","위쪽부터 차례로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#16','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 고슴도치와 함께 잎 아래에 선 동물은 누구인가요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":16,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 고슴도치와 함께 잎 아래에 선 동물은 누구인가요?","options":[{"t":"개구리","correct":true},{"t":"다람쥐","mis":"K1-1-u2-X14"},{"t":"거북","mis":"K1-1-u2-X14"}],"explanation":["고슴도치는 개구리와 함께 섰어요.","다람쥐·거북은 이 이야기에 없어요.","「누구와」를 기억해요."],"asset":{"type":"passage","lines":["비 오는 날, 고슴도치가 커다란 잎을 우산처럼 썼어요.","고슴도치는 비를 맞는 개구리와 함께 잎 아래에 섰어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#17','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C1',3,'error','auto','지안이가 받침이 있는 글자만 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#18','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C3',3,'error','auto','시우가 「고」에 받침 ㅁ을 더해 「고ㅁ」처럼 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X05','K1-1-u2-X06']::text[],false,'{"seq":18,"concept":"K1-1-u2-C3","difficulty":3,"kind":"error","stem":"시우가 「고」에 받침 ㅁ을 더해 「고ㅁ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「곰」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㅁ 대신 ㅂ을 더해야 해요 — 「곱」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「굼」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","고 + 받침 ㅁ = 곰.","옆에 따로 쓰면 한 글자가 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#19','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C4',3,'error','auto','은솔이가 「장갑」을 「자갑」이라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05','K1-1-u2-X03']::text[],false,'{"seq":19,"concept":"K1-1-u2-C4","difficulty":3,"kind":"error","stem":"은솔이가 「장갑」을 「자갑」이라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「장」의 받침 ㅇ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「장」의 받침을 ㄴ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「장」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「장」에는 받침 ㅇ이 있어요.","받침을 빼면 다른 말처럼 들려요.","받침 소리까지 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#20','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C5',3,'mc','auto','「고」에 받침을 붙여 「숲에 사는 커다란 동물」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],false,'{"seq":20,"concept":"K1-1-u2-C5","difficulty":3,"kind":"mc","stem":"「고」에 받침을 붙여 「숲에 사는 커다란 동물」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㅁ — 「곰」","correct":true},{"t":"받침 ㅂ — 「곱」","mis":"K1-1-u2-X05"},{"t":"받침 ㄷ — 「곧」","mis":"K1-1-u2-X10"}],"explanation":["고 + 받침 ㅁ = 곰.","받침이 다르면 뜻이 달라요.","뜻을 생각해 받침을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#21','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C6',3,'mc','auto','하린이는 발표할 때 친구들을 보고 또박또박 말했어요. 그런데 손으로 머리카락을 계속 꼬았어요. 하린에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X11','K1-1-u2-X12']::text[],false,'{"seq":21,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"하린이는 발표할 때 친구들을 보고 또박또박 말했어요. 그런데 손으로 머리카락을 계속 꼬았어요. 하린에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"손을 자연스럽게 내려 봐","correct":true},{"t":"친구들을 보지 말고 말해 봐","mis":"K1-1-u2-X11"},{"t":"더 빨리 말해 봐","mis":"K1-1-u2-X12"}],"explanation":["하린이가 고칠 것은 하나예요.","잘한 것은 두고 고칠 점만 말해 줘요.","다섯 가지 자세 — 눈·허리·손·다리·목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#22','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C8',3,'error','auto','지안이가 그림을 보고 「가반」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10','K1-1-u2-X03']::text[],false,'{"seq":22,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"지안이가 그림을 보고 「가반」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「방」의 받침을 ㅇ 대신 ㄴ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"다른 글자에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자를 바꿔 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「가방」 — 받침 ㅇ.","소리가 비슷한 받침과 헷갈렸어요.","그림의 뜻에 맞는 받침을 넣어요."],"asset":{"type":"bat_word","w":"가방","at":1,"pic":"🎒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#23','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C4',4,'mc','auto','다음 글에서 받침 ㅇ이 들어간 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X15']::text[],false,'{"seq":23,"concept":"K1-1-u2-C4","difficulty":4,"kind":"mc","stem":"다음 글에서 받침 ㅇ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u2-X15"},{"t":"6개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㅇ 글자: 동 · 생 · 공 · 방.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["동생이 공을 들고 방으로 왔어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#24','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C2',4,'essay','teacher','「고」와 「곰」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-1-u2-C2","difficulty":4,"kind":"essay","stem":"「고」와 「곰」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.","answer_guide":{"answer":"예: 「곰」은 「고」의 아래쪽에 받침 ㅁ이 들어갔어요. 받침 소리까지 읽으면 끝소리가 달라져요.","scoring_points":["받침이 아래쪽에 들어갔다고 말했는가","받침 ㅁ을 바르게 찾았는가","소리가 달라졌다고 말했는가"]},"explanation":["받침 자리는 아래쪽.","받침은 ㅁ.","받침이 생기면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_c#25','kor',1,1,'u2','','g1_1_kor_u2_review_c','unit_review','K1-1-u2-C8',4,'mc','auto','받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],false,'{"seq":25,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"풍선","correct":true},{"t":"푼선","mis":"K1-1-u2-X05"},{"t":"풍서","mis":"K1-1-u2-X04"}],"explanation":["푸 + ㅇ = 풍, 서 + ㄴ = 선.","「푼선」은 비슷한 받침을, 「풍서」는 받침 하나를 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"🎈","text":"푸□ 서□"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#1','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C1',1,'mc','auto','받침이 있는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":1,"kind":"mc","stem":"받침이 있는 글자는 어느 것인가요?","options":[{"t":"집","correct":true},{"t":"지","mis":"K1-1-u2-X01"},{"t":"코","mis":"K1-1-u2-X01"}],"explanation":["「집」은 아래쪽에 받침 ㅂ이 있어요.","「지」·「코」는 아래쪽이 비어 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":1,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#2','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C2',1,'mc','auto','「집」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":2,"kind":"mc","stem":"「집」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"집","eq":false,"lay":"blank"},"options":[{"t":"ㅂ","correct":true},{"t":"ㅈ","mis":"K1-1-u2-X03"},{"t":"ㅁ","mis":"K1-1-u2-X05"}],"explanation":["「집」은 ㅈ + ㅣ + 받침 ㅂ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅈ은 첫소리, 받침 ㅂ은 끝소리예요."],"concept":"K1-1-u2-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#3','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C3',1,'mc','auto','「무」에 받침 ㄹ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05']::text[],true,'{"seq":3,"kind":"mc","stem":"「무」에 받침 ㄹ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"무","b":"ㄹ","s":null,"lay":true},"options":[{"t":"물","correct":true},{"t":"무","mis":"K1-1-u2-X04"},{"t":"문","mis":"K1-1-u2-X05"}],"explanation":["「무」 아래쪽에 받침 ㄹ을 더하면 「물」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「물」은 받침 ㄹ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X04","near":"X05"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#4','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C4',1,'mc','auto','입술을 한 번 톡 닫는 받침 ㅂ이 들어간 글자는 어느 것인가요?',ARRAY['K1-1-u2-X05']::text[],false,'{"seq":4,"concept":"K1-1-u2-C4","difficulty":1,"kind":"mc","stem":"입술을 한 번 톡 닫는 받침 ㅂ이 들어간 글자는 어느 것인가요?","options":[{"t":"집","correct":true},{"t":"짐","mis":"K1-1-u2-X05"},{"t":"진","mis":"K1-1-u2-X05"}],"explanation":["「집」은 받침 ㅂ — 입술을 톡 닫아요.","「짐」은 ㅁ, 「진」은 ㄴ이에요.","ㅁ과 ㅂ을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#5','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C6',1,'mc','auto','발표할 때 다리는 어떻게 하나요?',ARRAY['K1-1-u2-X11']::text[],false,'{"seq":5,"concept":"K1-1-u2-C6","difficulty":1,"kind":"mc","stem":"발표할 때 다리는 어떻게 하나요?","options":[{"t":"어깨너비만큼 벌리고 편안하게 서요","correct":true},{"t":"다리를 꼬고 서요","mis":"K1-1-u2-X11"},{"t":"한 발로 콩콩 뛰어요","mis":"K1-1-u2-X11"}],"explanation":["다리를 어깨너비로 벌리면 몸이 흔들리지 않아요.","꼬거나 뛰면 발표가 불안해 보여요.","발표 자세 — 다리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#6','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C7',1,'mc','auto','이야기를 들을 때 다리는 어떻게 하나요?',ARRAY['K1-1-u2-X13']::text[],false,'{"seq":6,"concept":"K1-1-u2-C7","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 다리는 어떻게 하나요?","options":[{"t":"가지런히 모아요","correct":true},{"t":"계속 흔들어요","mis":"K1-1-u2-X13"},{"t":"책상 위에 올려요","mis":"K1-1-u2-X13"}],"explanation":["다리는 가지런히 모아요.","흔들면 옆 친구도 집중하기 어려워요.","듣기 자세 — 다리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#7','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C8',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"손","at":0,"pic":"✋"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅇ","mis":"K1-1-u2-X05"},{"t":"ㅅ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「손」이에요.","「소」에 받침 ㄴ을 넣어야 「손」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#8','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C2',1,'mc','auto','「집」에서 받침 ㅂ은 어디에 있나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X03']::text[],false,'{"seq":8,"concept":"K1-1-u2-C2","difficulty":1,"kind":"mc","stem":"「집」에서 받침 ㅂ은 어디에 있나요?","options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u2-X02"},{"t":"위쪽 왼쪽","mis":"K1-1-u2-X03"}],"explanation":["받침 ㅂ은 「집」의 아래쪽에 있어요.","오른쪽은 ㅣ, 위쪽 왼쪽은 ㅈ 자리예요.","받침은 아래쪽."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#9','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C1',2,'mc','auto','받침이 없는 글자는 어느 것인가요?',ARRAY['K1-1-u2-X01']::text[],true,'{"seq":9,"kind":"mc","stem":"받침이 없는 글자는 어느 것인가요?","options":[{"t":"구","correct":true},{"t":"국","mis":"K1-1-u2-X01"},{"t":"별","mis":"K1-1-u2-X01"}],"explanation":["「구」는 아래쪽이 비어 있어요.","「국」·「별」은 아래쪽에 받침이 있어요.","글자 아래쪽에 자음자가 있는지 살펴봐요."],"concept":"K1-1-u2-C1","difficulty":2,"variant_rule":{"bat":{"ask":"has","mis":{"none":"X01"},"neg":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#10','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C3',2,'mc','auto','도 + 받침 ㄴ 는 어떤 글자가 되나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X06']::text[],true,'{"seq":10,"kind":"mc","stem":"도 + 받침 ㄴ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"도","b":"ㄴ","s":null},"options":[{"t":"돈","correct":true},{"t":"도ㄴ","mis":"K1-1-u2-X02"},{"t":"둔","mis":"K1-1-u2-X06"}],"explanation":["「도」 아래쪽에 받침 ㄴ을 더하면 「돈」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「돈」은 받침 ㄴ 소리까지 끝까지 읽어요."],"concept":"K1-1-u2-C3","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#11','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C4',2,'mc','auto','「섬」의 받침은 어느 것인가요?',ARRAY['K1-1-u2-X03','K1-1-u2-X05']::text[],true,'{"seq":11,"kind":"mc","stem":"「섬」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"섬","eq":false},"options":[{"t":"ㅁ","correct":true},{"t":"ㅅ","mis":"K1-1-u2-X03"},{"t":"ㅂ","mis":"K1-1-u2-X05"}],"explanation":["「섬」은 ㅅ + ㅓ + 받침 ㅁ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅅ은 첫소리, 받침 ㅁ은 끝소리예요."],"concept":"K1-1-u2-C4","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X03","near":"X05"},"bats":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#12','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C5',2,'mc','auto','「강」의 받침 ㅇ을 ㄴ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u2-X09','K1-1-u2-X08']::text[],true,'{"seq":12,"kind":"mc","stem":"「강」의 받침 ㅇ을 ㄴ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"강","eq":false},"options":[{"t":"간","correct":true},{"t":"낭","mis":"K1-1-u2-X09"},{"t":"강","mis":"K1-1-u2-X08"}],"explanation":["「강」에서 받침 ㅇ 자리에 ㄴ을 넣으면 「간」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u2-C5","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X09","keep":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#13','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C5',2,'ox','auto','「산」과 「상」은 받침만 다르니 뜻이 같아요.',ARRAY['K1-1-u2-X08']::text[],false,'{"seq":13,"concept":"K1-1-u2-C5","difficulty":2,"kind":"ox","stem":"「산」과 「상」은 받침만 다르니 뜻이 같아요.","answer":"X","reason_options":[{"t":"받침이 바뀌면 소리도 뜻도 달라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 글자니까","mis":"K1-1-u2-X08"}],"mis":"K1-1-u2-X08","explanation":["「산」은 높은 땅, 「상」은 상을 받을 때의 상.","받침 하나가 달라도 다른 글자예요.","받침까지 보고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#14','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C8',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u2-X05','K1-1-u2-X03']::text[],true,'{"seq":14,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"가방","at":1,"pic":"🎒"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u2-X05"},{"t":"ㅂ","mis":"K1-1-u2-X03"}],"explanation":["그림은 「가방」이에요.","「바」에 받침 ㅇ을 넣어야 「방」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u2-C8","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X05","role":"X03"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#15','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C2',2,'mc','auto','「책」을 세 부분으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u2-X07','K1-1-u2-X03']::text[],false,'{"seq":15,"concept":"K1-1-u2-C2","difficulty":2,"kind":"mc","stem":"「책」을 세 부분으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㅊ + ㅐ + 받침 ㄱ","correct":true},{"t":"ㅊ + ㄱ + 받침 ㅐ","mis":"K1-1-u2-X07"},{"t":"ㄱ + ㅐ + 받침 ㅊ","mis":"K1-1-u2-X03"}],"explanation":["「책」은 첫 자음자 ㅊ, 모음자 ㅐ, 받침 ㄱ이에요.","모음자는 받침이 될 수 없고, 첫 자음자와 받침은 자리가 달라요.","위쪽부터 차례로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#16','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C7',2,'mc','auto','이야기를 듣고 답해요. 생쥐는 빵을 몇 개 샀나요?',ARRAY['K1-1-u2-X14']::text[],false,'{"seq":16,"concept":"K1-1-u2-C7","difficulty":2,"kind":"mc","stem":"이야기를 듣고 답해요. 생쥐는 빵을 몇 개 샀나요?","options":[{"t":"두 개","correct":true},{"t":"한 개","mis":"K1-1-u2-X14"},{"t":"세 개","mis":"K1-1-u2-X14"}],"explanation":["생쥐는 빵을 두 개 샀어요.","하나는 먹고 하나는 토끼에게 주었어요.","「얼마나」를 기억해요."],"asset":{"type":"passage","lines":["아침에 생쥐가 빵집에 갔어요.","생쥐는 빵을 두 개 샀어요.","하나는 자기가 먹고, 하나는 아픈 토끼에게 주었어요."],"title":"들은 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#17','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C1',3,'error','auto','로아가 받침이 있는 글자만 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#18','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C3',3,'error','auto','다은이가 「바」에 받침 ㅂ을 더해 「바ㅂ」처럼 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X02','K1-1-u2-X05','K1-1-u2-X06']::text[],false,'{"seq":18,"concept":"K1-1-u2-C3","difficulty":3,"kind":"error","stem":"다은이가 「바」에 받침 ㅂ을 더해 「바ㅂ」처럼 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 아래쪽에 써야 해요 — 「밥」","correct":true,"mis_target":"K1-1-u2-X02"},{"t":"ㅂ 대신 ㅁ을 더해야 해요 — 「밤」","mis":"K1-1-u2-X05"},{"t":"받침을 더하면 모음자도 바꿔야 해요 — 「법」","mis":"K1-1-u2-X06"}],"explanation":["받침은 글자 아래쪽에 들어가요.","바 + 받침 ㅂ = 밥.","옆에 따로 쓰면 한 글자가 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#19','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C4',3,'error','auto','태민이가 「사슴」을 「사스」라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X04','K1-1-u2-X05','K1-1-u2-X03']::text[],false,'{"seq":19,"concept":"K1-1-u2-C4","difficulty":3,"kind":"error","stem":"태민이가 「사슴」을 「사스」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"「슴」의 받침 ㅁ을 빼고 읽었어요","correct":true,"mis_target":"K1-1-u2-X04"},{"t":"「슴」의 받침을 ㅂ으로 읽었어요","mis":"K1-1-u2-X05"},{"t":"「슴」의 첫 자음자를 바꿔 읽었어요","mis":"K1-1-u2-X03"}],"explanation":["「슴」에는 받침 ㅁ이 있어요.","받침을 빼면 다른 말처럼 들려요.","받침 소리까지 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#20','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C5',3,'mc','auto','「다」에 받침을 붙여 「밤하늘에 뜨는 둥근 것」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10']::text[],false,'{"seq":20,"concept":"K1-1-u2-C5","difficulty":3,"kind":"mc","stem":"「다」에 받침을 붙여 「밤하늘에 뜨는 둥근 것」을 뜻하는 글자를 만들려면 어떤 받침을 붙이나요?","options":[{"t":"받침 ㄹ — 「달」","correct":true},{"t":"받침 ㄴ — 「단」","mis":"K1-1-u2-X05"},{"t":"받침 ㅇ — 「당」","mis":"K1-1-u2-X10"}],"explanation":["다 + 받침 ㄹ = 달.","받침이 다르면 뜻이 달라요.","뜻을 생각해 받침을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#21','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C6',3,'mc','auto','시우는 발표할 때 친구들을 보고 손을 내렸어요. 그런데 몸을 이리저리 흔들었어요. 시우에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u2-X11','K1-1-u2-X12']::text[],false,'{"seq":21,"concept":"K1-1-u2-C6","difficulty":3,"kind":"mc","stem":"시우는 발표할 때 친구들을 보고 손을 내렸어요. 그런데 몸을 이리저리 흔들었어요. 시우에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"다리를 어깨너비로 벌리고 바르게 서 봐","correct":true},{"t":"눈을 감고 말해 봐","mis":"K1-1-u2-X11"},{"t":"목소리를 아주 크게 소리쳐 봐","mis":"K1-1-u2-X12"}],"explanation":["시우가 고칠 것은 하나예요.","잘한 것은 두고 고칠 점만 말해 줘요.","다섯 가지 자세 — 눈·허리·손·다리·목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#22','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C8',3,'error','auto','민호가 그림을 보고 「풍성」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u2-X05','K1-1-u2-X10','K1-1-u2-X03']::text[],false,'{"seq":22,"concept":"K1-1-u2-C8","difficulty":3,"kind":"error","stem":"민호가 그림을 보고 「풍성」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「선」의 받침을 ㄴ 대신 ㅇ으로 썼어요","correct":true,"mis_target":"K1-1-u2-X05"},{"t":"다른 글자에도 받침을 넣어야 해요","mis":"K1-1-u2-X10"},{"t":"첫 자음자를 바꿔 써야 해요","mis":"K1-1-u2-X03"}],"explanation":["그림은 「풍선」 — 받침 ㄴ.","소리가 비슷한 받침과 헷갈렸어요.","그림의 뜻에 맞는 받침을 넣어요."],"asset":{"type":"bat_word","w":"풍선","at":1,"pic":"🎈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#23','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C4',4,'mc','auto','다음 글에서 받침 ㄴ이 들어간 글자는 모두 몇 개인가요?',ARRAY['K1-1-u2-X15']::text[],false,'{"seq":23,"concept":"K1-1-u2-C4","difficulty":4,"kind":"mc","stem":"다음 글에서 받침 ㄴ이 들어간 글자는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u2-X15"},{"t":"5개","mis":"K1-1-u2-X15"}],"explanation":["받침 ㄴ 글자: 친 · 손 · 문.","다른 받침이나 받침 없는 글자는 세지 않아요.","글자 하나하나 짚으며 세요."],"asset":{"type":"passage","lines":["친구가 손에 빵을 들고 문을 열었어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#24','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C2',4,'essay','teacher','「무」와 「물」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-1-u2-C2","difficulty":4,"kind":"essay","stem":"「무」와 「물」의 짜임을 견주어, 받침이 어디에 들어갔는지와 소리가 어떻게 달라졌는지 말해 보세요.","answer_guide":{"answer":"예: 「물」은 「무」의 아래쪽에 받침 ㄹ이 들어갔어요. 받침 소리까지 읽으면 끝소리가 달라져요.","scoring_points":["받침이 아래쪽에 들어갔다고 말했는가","받침 ㄹ을 바르게 찾았는가","소리가 달라졌다고 말했는가"]},"explanation":["받침 자리는 아래쪽.","받침은 ㄹ.","받침이 생기면 끝소리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u2_review_d#25','kor',1,1,'u2','','g1_1_kor_u2_review_d','unit_review','K1-1-u2-C8',4,'mc','auto','받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u2-X05','K1-1-u2-X04']::text[],false,'{"seq":25,"concept":"K1-1-u2-C8","difficulty":4,"kind":"mc","stem":"받침이 빠진 그림 낱말에 받침을 넣어 바르게 쓴 것은 어느 것인가요?","options":[{"t":"운동장","correct":true},{"t":"운돈장","mis":"K1-1-u2-X05"},{"t":"우동장","mis":"K1-1-u2-X04"}],"explanation":["우 + ㄴ = 운, 도 + ㅇ = 동, 자 + ㅇ = 장.","「운돈장」은 비슷한 받침을, 「우동장」은 받침 하나를 빼먹었어요.","두 받침을 다 챙겨요."],"asset":{"type":"scene","icon":"🏟️","text":"우□ 도□ 자□"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
